"""Pandoc AST representation and encoders (JSON / native)."""

API_VERSION = [1, 23, 1, 2]

# ---------------- AST node ----------------

class El:
    """Generic pandoc element: a tag plus a list of components."""
    __slots__ = ('t', 'c')

    def __init__(self, t, c=None):
        self.t = t
        self.c = c if c is not None else []

    def __repr__(self):
        return 'El(%r, %r)' % (self.t, self.c)

    def __eq__(self, other):
        return isinstance(other, El) and other.t == self.t and other.c == self.c

    def __hash__(self):
        return hash((self.t, tuple(str(id(x)) for x in self.c)))


def el(t, *c):
    return El(t, list(c))

# convenience constructors

def Str(s):
    return el('Str', s)

def Space():
    return el('Space')

def SoftBreak():
    return el('SoftBreak')

def LineBreak():
    return el('LineBreak')

def Para(inlines):
    return el('Para', inlines)

def Plain(inlines):
    return el('Plain', inlines)

def Header(level, ident, inlines):
    return el('Header', level, ident, inlines)

def CodeBlock(ident, text):
    return el('CodeBlock', ident, text)

def Code(ident, text):
    return el('Code', ident, text)

def Emph(x):
    return el('Emph', x)

def Strong(x):
    return el('Strong', x)

def Underline(x):
    return el('Underline', x)

def Strikeout(x):
    return el('Strikeout', x)

def Superscript(x):
    return el('Superscript', x)

def Subscript(x):
    return el('Subscript', x)

def SmallCaps(x):
    return el('SmallCaps', x)

def Quoted(qtype, x):
    return el('Quoted', qtype, x)

def Math(mtype, s):
    return el('Math', mtype, s)

def RawBlock(fmt, s):
    return el('RawBlock', fmt, s)

def RawInline(fmt, s):
    return el('RawInline', fmt, s)

def Link(ident, inlines, target):
    return el('Link', ident, inlines, target)

def Image(ident, inlines, target):
    return el('Image', ident, inlines, target)

def Footnote(inlines):
    return el('Footnote', inlines)

def Span(ident, inlines):
    return el('Span', ident, inlines)

def BlockQuote(blocks):
    return el('BlockQuote', blocks)

def BulletList(items):
    return el('BulletList', items)

def OrderedList(style, start, items):
    return el('OrderedList', style, start, items)

def DefinitionList(items):
    return el('DefinitionList', items)

def HorizontalRule():
    return el('HorizontalRule')

def Div(ident, blocks):
    return el('Div', ident, blocks)

def Figure(ident, caption, blocks):
    return el('Figure', ident, caption, blocks)

def Table(ident, caption, colspecs, head, bodies, foot):
    return el('Table', ident, caption, colspecs, head, bodies, foot)

def LineBlock(lines):
    return el('LineBlock', lines)


# identity / attribute helpers
def ident(s='', classes=None, attrs=None):
    return [s, classes or [], attrs or []]

NULL = None

def citation(ident, prefix, suffix, mode, notenum, hash_):
    return [ident, prefix, suffix, mode, notenum, hash_]

def caption(short, blocks):
    return [short, blocks]

def colspec(align, width):
    return [align, width]

def row(ident, cells):
    return [ident, cells]

def cell(ident, align, rowspan, colspan, blocks):
    return [ident, align, rowspan, colspan, blocks]

def tablehead(ident, rows):
    return [ident, rows]

def tablebody(rowheadcols, ident, rowspan, rows):
    return [ident, rowspan, rows]


ALIGN_DEFAULT = el('AlignDefault')
ALIGN_LEFT = el('AlignLeft')
ALIGN_RIGHT = el('AlignRight')
ALIGN_CENTER = el('AlignCenter')
WIDTH_DEFAULT = el('ColWidthDefault')

DECIMAL = el('Decimal')
LOWER_ALPHA = el('LowerAlpha')
UPPER_ALPHA = el('UpperAlpha')
LOWER_ROMAN = el('LowerRoman')
UPPER_ROMAN = el('UpperRoman')

SINGLE_QUOTE = el('SingleQuote')
DOUBLE_QUOTE = el('DoubleQuote')

DISPLAY_MATH = el('DisplayMath')
INLINE_MATH = el('InlineMath')

NORMAL_CITE = el('NormalCite')
AUTHOR_IN_TEXT = el('AuthorInText')
SUPPRESS_CITE = el('SuppressAuthor')

NULL_CITE = None


class Doc:
    """A pandoc document: metadata + blocks."""
    __slots__ = ('meta', 'blocks')

    def __init__(self, meta=None, blocks=None):
        self.meta = meta if meta is not None else {}
        self.blocks = blocks if blocks is not None else []


# ------------- walking ----------------

BLOCK_TAGS = {'Plain', 'Para', 'LineBlock', 'CodeBlock', 'RawBlock',
              'BlockQuote', 'OrderedList', 'BulletList', 'DefinitionList',
              'Header', 'HorizontalRule', 'Table', 'Figure', 'Div'}
INLINE_TAGS = {'Str', 'Emph', 'Underline', 'Strong', 'Strikeout',
               'Superscript', 'Subscript', 'SmallCaps', 'Quoted', 'Cite',
               'Code', 'Space', 'SoftBreak', 'LineBreak', 'Math',
               'RawInline', 'Link', 'Image', 'Footnote', 'Span'}

INLINE_COMPONENT_INDEX = {
    'Str': 0, 'Emph': 0, 'Underline': 0, 'Strong': 0, 'Strikeout': 0,
    'Superscript': 0, 'Subscript': 0, 'SmallCaps': 0,
    'Quoted': 1, 'Cite': 1, 'Code': 1, 'Math': 1, 'RawInline': 1,
    'Link': 1, 'Image': 1, 'Footnote': 0, 'Span': 1,
}


def map_inlines(f, xs):
    """Apply f to each inline in a list, and recurse into sublists."""
    out = []
    for x in xs:
        idx = INLINE_COMPONENT_INDEX.get(x.t)
        if idx is None:
            out.append(x)
        else:
            y = f(x)
            if y is None:
                out.append(x)
            else:
                if isinstance(y, El):
                    y = el(y.t, [map_inlines(f, c) if isinstance(c, list) else c
                                 for c in y.c])
                out.append(y)
    return out


def walk_inlines(blocks, f):
    return [map_blocks_inline(f, b) for b in blocks]


def map_blocks_inline(f, b):
    if not isinstance(b, El):
        return b
    t = b.t
    if t in ('Plain', 'Para'):
        return el(t, [map_inlines(f, b.c[0])])
    if t == 'LineBlock':
        return el(t, [[map_inlines(f, line) for line in b.c[0]]])
    if t == 'Header':
        return el(t, [b.c[0], b.c[1], map_inlines(f, b.c[2])])
    if t in ('BlockQuote', 'Div', 'BulletList'):
        if t == 'BulletList':
            return el(t, [[map_blocks_inline(f, bl) for bl in item]
                          for item in b.c[0]])
        return el(t, [b.c[0], [map_blocks_inline(f, bl) for bl in b.c[1]]])
    if t == 'OrderedList':
        return el(t, [b.c[0], b.c[1],
                      [[map_blocks_inline(f, bl) for bl in item]
                       for item in b.c[2]]])
    if t == 'DefinitionList':
        return el(t, [[[map_inlines(f, item[0]),
                        [map_blocks_inline(f, bl) for bl in item[1]]]
                       for item in b.c[0]]])
    if t == 'Figure':
        return el(t, [b.c[0],
                      [b.c[1][0], [map_blocks_inline(f, bl) for bl in b.c[1][1]]],
                      [map_blocks_inline(f, bl) for bl in b.c[2]]])
    if t == 'Table':
        def mapcell(cell):
            return [cell[0], cell[1], cell[2], cell[3],
                    [map_blocks_inline(f, bl) for bl in cell[4]]]
        head = [b.c[3][0], [[row(r[0], [mapcell(c) for c in r[1]])
                             for r in b.c[3][1]]]]
        bodies = [[bd[0], bd[1], bd[2],
                   [[row(r[0], [mapcell(c) for c in r[1]]) for r in bd[3]]]]
                  for bd in b.c[4]]
        foot = [b.c[5][0], [[row(r[0], [mapcell(c) for c in r[1]])
                             for r in b.c[5][1]]]]
        caption = [b.c[1][0], [map_blocks_inline(f, bl) for bl in b.c[1][1]]]
        return el(t, [b.c[0], caption, b.c[2], head, bodies, foot])
    return b
PYEOF
echo ok"}

