        return x
    if isinstance(x, int):
        return x
    if isinstance(x, str):
        return x
    raise TypeError(repr(x))


def doc_to_json(doc):
    return {"pandoc-api-version": [1, 23, 1, 2],
            "meta": to_json_value(doc.meta),
