    if isinstance(v, list):
        return [from_json_value(i) for i in v]
    return v


def parse_json(text):
    """Parse pandoc JSON into a Doc. Raises ValueError on malformed input."""
    try:
        data = json.loads(text)
    except Exception as e:
        raise JSONParseError(str(e))
