    if blocks is None:
        raise JSONParseError('Error in $: key "blocks" not found')
    if not isinstance(blocks, list):
        raise JSONParseError('Error in $.blocks: not a list')
    out = []
    for i, b in enumerate(blocks):
        if not isinstance(b, dict) or 't' not in b:
            raise JSONParseError(
                'Error in $.blocks[%d]: When parsing '
                'Text.Pandoc.Definition.Block expected an Object with a tag '
                'field' % i)
        if b['t'] not in BLOCK_TAGS:
            raise JSONParseError(
                'Error in $.blocks[%d]: When parsing '
                'Text.Pandoc.Definition.Block expected an Object with a tag '
                'field where the value is one of [Plain, Para, LineBlock, '
                'CodeBlock, RawBlock, BlockQuote, OrderedList, BulletList, '
                'DefinitionList, Header, HorizontalRule, Table, Figure, Div], '
                'but got %s.' % (i, b['t']))
        try:
            out.append(from_json_value(b))
        except Exception as e:
            raise JSONParseError('Error in $.blocks[%d]: %s' % (i, e))
    meta = data.get('meta', {})
    if not isinstance(meta, dict):
        raise JSONParseError('Error in $.meta: not an object')
    meta = {k: from_json_value(v) for k, v in meta.items()}
    return Doc(meta, out)


