"""Native (Haskell-style) writer for the pandoc AST, including a
HughesPJ-style pretty printer."""

WIDTH = 60


class Cat:
    """Concatenation without separators."""
    __slots__ = ('parts',)

    def __init__(self, *parts):
        self.parts = parts


class G:
    """A 'sep' group: flat = items joined by spaces; broken = first item on
    the current line, the rest on their own lines at indent startcol+offset."""
    __slots__ = ('items', 'offset')

    def __init__(self, items, offset):
        self.items = items
        self.offset = offset


# ---------------- pretty printer ----------------

def _flat_width(x):
    if isinstance(x, str):
        return len(x)
    if isinstance(x, Cat):
        return sum(_flat_width(p) for p in x.parts)
    if isinstance(x, G):
        return _flat_width_list(x.items)
    return 0


def _flat_width_list(items):
    w = 0
    for i, it in enumerate(items):
        w += _flat_width(it)
        if i < len(items) - 1:
            w += 1
    return w


def _fits(col, items):
    c = col
    for i, it in enumerate(items):
        if isinstance(it, G):
            if not _fits(c, it.items):
                return False
            c += _flat_width_list(it.items)
        elif isinstance(it, Cat):
            if not _fits(c, it.parts):
                return False
            c += _flat_width(it)
        else:
            c += len(it)
        if i < len(items) - 1:
            c += 1
        if c > WIDTH:
            return False
    return True


def _render(items, col, out):
    for i, it in enumerate(items):
        col = _render_atom(it, col, out)
        if i < len(items) - 1:
            out.append(' ')
            col += 1
    return col


def _render_atom(x, col, out):
    if isinstance(x, str):
        out.append(x)
        return col + len(x)
    if isinstance(x, Cat):
        for p in x.parts:
            col = _render_atom(p, col, out)
        return col
    if isinstance(x, G):
        if _fits(col, x.items):
            return _render(x.items, col, out)
        indent = col + x.offset
        col = _render_atom(x.items[0], col, out)
        for it in x.items[1:]:
            out.append('\n')
            out.append(' ' * indent)
            col = _render_atom(it, indent, out)
        return col
    return col


def render(x):
    out = []
    _render_atom(x, 0, out)
    return ''.join(out)


# ---------------- doc builders ----------------

def tup(*items):
    """( a , b , ... )"""
    items = list(items)
    if not items:
        return '()'
    body = [Cat('(', items[0])] + [Cat(', ', i) for i in items[1:]]
    return G(body + [')'], 0)


def lst(items):
    """[ a , b , ... ]"""
    items = list(items)
    if not items:
        return '[]'
    body = [Cat('[', items[0])] + [Cat(', ', i) for i in items[1:]]
    return G(body + [']'], 0)


def rec(name, *items):
    """Name arg1 arg2 ..."""
    items = list(items)
    if not items:
        return name
    return G([name] + items, 2)


def pretty_text(s):
    return '"%s"' % hs_string(s)


def hs_string(s):
    out = []
    prev_num = False
    for ch in s:
        o = ord(ch)
        if ch == '\\':
            out.append('\\\\')
            prev_num = False
        elif ch == '"':
            out.append('\\"')
            prev_num = False
        elif ch == '\n':
            out.append('\\n')
            prev_num = False
        elif ch == '\t':
            out.append('\\t')
            prev_num = False
        elif ch == '\r':
            out.append('\\r')
            prev_num = False
        elif 0x20 <= o <= 0x7e:
            out.append(ch)
            prev_num = False
        else:
            esc = _named.get(o)
            if esc is None:
                esc = '\\%d' % o
                out.append(esc)
                if prev_num:
                    out.append('\\&')
                out.append(esc[1:])
                # numeric escape: may need \& before a following digit
                esc_is_num = True
            else:
                out.append(esc)
                esc_is_num = False
            prev_num = esc_is_num
    return ''.join(out)


_named = {
    0: '\\NUL', 1: '\\SOH', 2: '\\STX', 3: '\\ETX', 4: '\\EOT', 5: '\\ENQ',
    6: '\\ACK', 7: '\\a', 8: '\\b', 9: '\\t', 10: '\\n', 11: '\\v', 12: '\\f',
