        elif ch == '"':
            out.append('\\"')
            prev_num = False
        elif ch == '\n':
            out.append('\\n')
            prev_num = False
        elif ch == '\t':
            out.append('\\t')
            prev_num = False
        elif ch == '\r':
            out.append('\\r')
            prev_num = False
        elif 0x20 <= o <= 0x7e:
            out.append(ch)
            prev_num = False
        else:
            esc = _named.get(o)
            if esc is None:
                esc = '\\%d' % o
                out.append(esc)
                if prev_num:
                    out.append('\\&')
                out.append(esc[1:])
                # numeric escape: may need \& before a following digit
                esc_is_num = True
            else:
                out.append(esc)
                esc_is_num = False
            prev_num = esc_is_num
    return ''.join(out)


_named = {
    0: '\\NUL', 1: '\\SOH', 2: '\\STX', 3: '\\ETX', 4: '\\EOT', 5: '\\ENQ',
    6: '\\ACK', 7: '\\a', 8: '\\b', 9: '\\t', 10: '\\n', 11: '\\v', 12: '\\f',
    13: '\\r', 14: '\\SO', 15: '\\SI', 16: '\\DLE', 17: '\\DC1', 18: '\\DC2',
    19: '\\DC3', 20: '\\DC4', 21: '\\NAK', 22: '\\SYN', 23: '\\ETB',
    24: '\\CAN', 25: '\\EM', 26: '\\SUB', 27: '\\ESC', 28: '\\FS',
    29: '\\GS', 30: '\\RS', 31: '\\US', 127: '\\DEL',
}


def pp_ident(a):
    return tup(pretty_text(a[0]),
               lst([pretty_text(c) for c in a[1]]),
               lst([tup(pretty_text(kv[0]), pretty_text(kv[1]))
                    for kv in a[2]]))


def pp_align(a):
    return a.t


def pp_width(w):
    if w.t == 'ColWidthDefault':
        return 'ColWidthDefault'
    return 'ColWidth %s' % _show_float(w.c[0])


def _show_float(f):
    s = repr(f)
    if s.endswith('.0'):
        s = s[:-2]
    return s


def pp_inline(x):
    t = x.t
    if t == 'Str':
        return rec('Str', pretty_text(x.c[0]))
    if t in ('Space', 'SoftBreak', 'LineBreak'):
        return t
    if t in ('Emph', 'Underline', 'Strong', 'Strikeout', 'Superscript',
             'Subscript', 'SmallCaps'):
        return rec(t, pp_inlines(x.c[0]))
    if t == 'Quoted':
        return rec('Quoted', x.c[0].t, pp_inlines(x.c[1]))
    if t == 'Cite':
        return rec('Cite', lst([pp_citation(c) for c in x.c[0]]),
                   pp_inlines(x.c[1]))
    if t == 'Code':
        return rec('Code', pp_ident(x.c[0]), pretty_text(x.c[1]))
    if t == 'Math':
        return rec('Math', x.c[0].t, pretty_text(x.c[1]))
    if t == 'RawInline':
        return rec('RawInline', rec('Format', pretty_text(x.c[0])),
                   pretty_text(x.c[1]))
    if t == 'Link':
        return rec('Link', pp_ident(x.c[0]), pp_inlines(x.c[1]),
                   tup(pretty_text(x.c[2][0]), pretty_text(x.c[2][1])))
    if t == 'Image':
        return rec('Image', pp_ident(x.c[0]), pp_inlines(x.c[1]),
                   tup(pretty_text(x.c[2][0]), pretty_text(x.c[2][1])))
    if t == 'Note':
        return rec('Note', pp_blocks(x.c[0]))
    if t == 'Span':
        return rec('Span', pp_ident(x.c[0]), pp_inlines(x.c[1]))
    return t


def pp_citation(c):
    fields = [
        'citationId = ' + pretty_text(c[0]),
        'citationPrefix = ' + pp_inlines(c[1]),
        'citationSuffix = ' + pp_inlines(c[2]),
        'citationMode = ' + c[3].t,
        'citationNoteNum = %d' % c[4],
        'citationHash = %d' % c[5],
    ]
    body = [Cat('{', fields[0])] + [Cat(', ', f) for f in fields[1:]]
    return rec('Citation', G(body + ['}'], 0))


def pp_blocks(bs):
    return lst([pp_block(b) for b in bs])


def pp_inlines(xs):
    return lst([pp_inline(x) for x in xs])


def pp_row(r):
    return rec('Row', pp_ident(r[0]), lst([pp_cell(c) for c in r[1]]))


def pp_cell(c):
    return rec('Cell', pp_ident(c[0]), pp_align(c[1]),
               'RowSpan %d' % c[2], 'ColSpan %d' % c[3],
               lst([pp_block(b) for b in c[4]]))


def pp_table_body(bd):
    return Cat('(', rec('TableBody', pp_ident(bd[0]),
                        'RowHeadColumns %d' % bd[1],
                        lst([pp_row(r) for r in bd[2]]),
                        lst([pp_row(r) for r in bd[3]])), ')')


def pp_table_head(h):
    return Cat('(', rec('TableHead', pp_ident(h[0]),
                        lst([pp_row(r) for r in h[1]])), ')')


def pp_table_foot(h):
    return Cat('(', rec('TableFoot', pp_ident(h[0]),
                        lst([pp_row(r) for r in h[1]])), ')')


def pp_caption(c):
    short = 'Nothing' if c[0] is None else 'Just ' + pp_inlines(c[0])
    return Cat('(', rec('Caption', short,
                        lst([pp_block(b) for b in c[1]])), ')')


def pp_block(b):
    t = b.t
    if t in ('Plain', 'Para'):
        return rec(t, pp_inlines(b.c[0]))
    if t == 'LineBlock':
        return rec('LineBlock', lst([pp_inlines(l) for l in b.c[0]]))
    if t == 'CodeBlock':
        return rec('CodeBlock', pp_ident(b.c[0]), pretty_text(b.c[1]))
    if t == 'RawBlock':
        return rec('RawBlock', rec('Format', pretty_text(b.c[0])),
                   pretty_text(b.c[1]))
    if t == 'BlockQuote':
        return rec('BlockQuote', pp_blocks(b.c[1]))
    if t == 'OrderedList':
        return rec('OrderedList',
                   tup(b.c[0][0], b.c[0][1].t, b.c[0][2].t),
                   lst([pp_blocks(item) for item in b.c[1]]))
    if t == 'BulletList':
        return rec('BulletList', lst([pp_blocks(item) for item in b.c[0]]))
    if t == 'DefinitionList':
        return rec('DefinitionList', lst([
            tup(pp_inlines(item[0]),
                lst([pp_blocks(d) for d in item[1]])) for item in b.c[0]]))
    if t == 'Header':
        return rec('Header', b.c[0], pp_ident(b.c[1]), pp_inlines(b.c[2]))
    if t == 'HorizontalRule':
        return 'HorizontalRule'
    if t == 'Table':
        return rec('Table', pp_ident(b.c[0]), pp_caption(b.c[1]),
                   lst([tup(pp_align(c[0]), pp_width(c[1])) for c in b.c[2]]),
                   pp_table_head(b.c[3]),
                   lst([pp_table_body(bd) for bd in b.c[4]]),
                   pp_table_foot(b.c[5]))
    if t == 'Figure':
        return rec('Figure', pp_ident(b.c[0]), pp_caption(b.c[1]),
                   lst([pp_block(bl) for bl in b.c[2]]))
    if t == 'Div':
        return rec('Div', pp_ident(b.c[0]), pp_blocks(b.c[1]))
    return t


# ---------------- meta ----------------

def pp_meta(m):
    if not m:
        return Cat('Meta', ' ', 'Meta {}')
    entries = []
    for k in sorted(m):
        entries.append(tup(pretty_text(k), pp_meta_value(m[k])))
    v = rec('fromList', lst(entries))
    field = G(['unMeta =', v], 2)
    return Cat('Meta', ' ', rec('Meta', G([Cat('{', field), '}'], 0)))


def pp_meta_value(v):
    if v is None:
        return 'Nothing'
    if isinstance(v, El):
        t = v.t
        if t == 'MetaString':
            return rec('MetaString', pretty_text(v.c[0]))
        if t == 'MetaBool':
            return rec('MetaBool', 'True' if v.c[0] else 'False')
        if t == 'MetaInlines':
            return rec('MetaInlines', pp_inlines(v.c[0]))
        if t == 'MetaList':
            return rec('MetaList', lst([pp_meta_value(i) for i in v.c[0]]))
        if t == 'MetaMap':
            return rec('MetaMap', 'fromList ' + _meta_map(v.c[0]))
        if t == 'MetaBlocks':
            return rec('MetaBlocks', pp_blocks(v.c[0]))
    return repr(v)


def _meta_map(d):
    entries = [tup(pretty_text(k), pp_meta_value(d[k])) for k in sorted(d)]
    return lst(entries)


def write_native(doc, standalone):
    if standalone:
        return render(rec('Pandoc', pp_meta(doc.meta),
                          pp_blocks(doc.blocks)))
    return render(pp_blocks(doc.blocks))
