"""A small implementation of the pandoc/doctemplates template language."""
import re

from . import data as datamod


def parse(src):
    """Parse a template string into a list of nodes."""
    nodes = []
    i = 0
    n = len(src)
    while i < n:
        c = src.find('$', i)
        if c < 0:
            nodes.append(('text', src[i:]))
            break
        if c > i:
            nodes.append(('text', src[i:c]))
        i = c + 1
        if i < n and src[i] == '$':
            nodes.append(('text', '$'))
            i += 1
            continue
        m = re.match(r'([A-Za-z0-9_\-]+)', src[i:])
        if not m:
            nodes.append(('text', '$'))
            continue
        name = m.group(1)
        i += len(name)
        # partial call?
        if i < n and src[i] == '(':
            j = src.find(')$', i)
            if j < 0:
                nodes.append(('text', '$' + name))
                continue
            args = src[i + 1:j]
            i = j + 2
            nodes.append(('partial', name, args))
            continue
        if i < n and src[i] == '$':
            i += 1
            if name == 'if':
                cond = _cond_expr(src, i)
                i = cond[1]
                body, end, elsebody = _read_block(src, cond[0], 'if', name)
                i = end
                nodes.append(('if', cond[2], body, elsebody))
            elif name == 'for':
                var = _ident(src, i)
                if var is None:
                    nodes.append(('text', '$for'))
                    continue
                i = var[1]
                body, end, elsebody = _read_block(src, i, 'for', name)
                i = end
                nodes.append(('for', var[2], body, elsebody))
            elif name in ('else', 'endif', 'endfor', 'sep'):
                nodes.append(('text', '$' + name))
            else:
                nodes.append(('var', name))
            continue
        nodes.append(('text', '$' + name))
    return nodes


def _ident(src, i):
    m = re.match(r'([A-Za-z0-9_\-]+)\$', src[i:])
    if m:
        return (None, i + m.end(), m.group(1))
    return None


def _cond_expr(src, i):
    m = re.match(r'([A-Za-z0-9_\-]+)\$', src[i:])
    if m:
        return (None, i + m.end(), m.group(1))
    return (None, i, '')


def _read_block(src, i, kind, name):
    """Read until $else$/$endif$/$endfor$ at depth, returns
    (body, index-after-end, elsebody)."""
    depth = 0
    body = []
    elsebody = None
    cur = []
    j = i
    n = len(src)
    while j < n:
        c = src.find('$', j)
        if c < 0:
            cur.append(src[j:])
            break
        if c > j:
            cur.append(src[j:c])
        j = c + 1
        if j < n and src[j] == '$':
            cur.append('$')
            j += 1
            continue
        m = re.match(r'([A-Za-z0-9_\-]+)\$', src[j:])
        if m:
            tok = m.group(1)
            j += m.end()
            if tok == kind:
                depth += 1
                cur.append('$' + tok + '$')
            elif tok == 'if' or tok == 'for':
                # skip nested constructs including their args
                if tok == 'if':
                    k = _skip_cond(src, j)
                else:
                    k = _skip_for(src, j)
                if k is None:
                    cur.append('$' + tok)
                    j = n
                    break
                depth += 1
                cur.append(src[j:k])
                j = k
            elif tok in ('endif', 'endfor'):
                if depth == 0:
                    break
                depth -= 1
                cur.append('$' + tok + '$')
            elif tok == 'else' and depth == 0:
                body = cur
                cur = []
                elsebody = []
                while elsebody is not None:
                    c2 = src.find('$', j)
                    if c2 < 0:
                        elsebody = None
                        j = n
                        break
                    m2 = re.match(r'([A-Za-z0-9_\-]+)\$', src[c2 + 1:])
                    if m2 and m2.group(1) == 'endif' and depth == 0:
                        j = c2 + 1 + m2.end()
                        break
                    if m2 is None:
                        elsebody.append(src[c2])
                        j = c2 + 1
                        continue
                    tok2 = m2.group(1)
                    if tok2 in ('if', 'for'):
                        k = _skip_block(src, c2 + 1, tok2)
                        if k is None:
                            elsebody.append(src[c2:])
                            j = n
                            break
                        elsebody.append(src[c2 + 1:k])
                        j = k
