"""Markdown reader (pandoc's Markdown flavour)."""
import re

from .ast import (El, el, Doc, Str, Space, Para, Plain, Header, CodeBlock,
                  BlockQuote, BulletList, OrderedList, DefinitionList,
                  HorizontalRule, Div, Figure, LineBlock, RawBlock, Table,
                  ALIGN_DEFAULT, ident, row, cell, colspec, tablehead,
                  tablebody, caption, citation, DECIMAL, LOWER_ALPHA,
                  UPPER_ALPHA, LOWER_ROMAN, UPPER_ROMAN, INLINE_MATH,
                  DISPLAY_MATH, SINGLE_QUOTE, DOUBLE_QUOTE, NORMAL_CITE,
                  AUTHOR_IN_TEXT, SUPPRESS_CITE, Math, Code, Emph, Strong,
                  Strikeout, Superscript, Subscript, Underline, SmallCaps,
                  Quoted, Link, Image, Span, Note, Cite, LineBreak, SoftBreak,
                  RawInline, map_blocks_inline, map_inlines)


# ---------------- extension sets ----------------

DEFAULT_EXTS = {}


def load_default_exts(fmt):
    """Return the set of enabled extensions for a reader format."""
    from . import data as datamod
    exts = set()
    for line in datamod.lines('extensions/%s.txt' % fmt):
        if not line:
            continue
        if line.startswith('+'):
            exts.add(line[1:])
        elif line.startswith('-'):
            exts.discard(line[1:])
    return exts


class Reader:
    """A markdown reader for the given format."""

    name = 'markdown'

    def __init__(self, fmt, opt_exts=None):
        self.fmt = fmt
        exts = load_default_exts(self.fmt)
        if opt_exts:
            for e, val in opt_exts:
                if val:
                    exts.add(e)
                else:
                    exts.discard(e)
        self.exts = exts

    def __getitem__(self, name):
        return name in self.exts


def parse_ext_spec(spec):
    """Parse "markdown+ext-ext" into (format, [(ext, bool)])."""
    if not spec:
        raise ValueError('empty')
    parts = spec.split('+')
    fmt = parts[0]
    exts = []
    for p in parts[1:]:
        if p.startswith('-'):
            exts.append((p[1:], False))
        else:
            exts.append((p, True))
    return fmt, exts


# ---------------- helpers ----------------

NBSP = '\xa0'


def text_to_inlines(s, sp=None):
    """Create inlines from a plain string, respecting spaces/nbsp."""
    if s is None or s == '':
        return []
    parts = re.split(r'[ \t\xa0]+', s)
    out = []
    first = True
    for p in parts:
        if p == '':
            continue
        if not first:
            out.append(Space())
        out.append(Str(p))
        first = False
    return out


# ---------------- the reader ----------------

class MdParser:
    def __init__(self, reader, opts=None):
        self.r = reader
        self.opts = opts
        self.meta = {}
        self.keyvals = {}       # link references: key -> (url, title)
        self.footnotes = {}     # id -> blocks

    def parse(self, text):
        self.lines = text.split('\n')
        if self.lines and self.lines[-1] == '':
            self.lines.pop()
        self.pos = 0
        blocks = self.parse_blocks()
        # move footnote definitions to the end
        fns = []
        self.remove_footnotes(blocks)
        for k in self.footnotes:
            fns.append(self.footnotes[k])
        return Doc(self.meta, blocks)

    def cur(self):
        if self.pos < len(self.lines):
            return self.lines[self.pos]
        return None

    def at(self, i):
        p = self.pos + i
        if p < len(self.lines):
            return self.lines[p]
        return None

    def eof(self):
        return self.pos >= len(self.lines)

    def blank(self, line):
        return line is not None and line.strip() == ''

    # ---------------- block parsing ----------------

    def parse_blocks(self):
        out = []
        while not self.eof():
            b = self.parse_block()
            if b is not None:
                out.extend(b if isinstance(b, list) else [b])
        return out

    def parse_block(self):
        line = self.cur()
        if line is None:
            return None
        # blank line
        if self.blank(line):
            self.pos += 1
            return None
        # raw HTML block
        if self.r['raw_html']:
            b = self.try_html_block()
            if b is not None:
                return b
        # fenced code
        b = self.try_fenced_code()
        if b is not None:
            return b
        # fenced divs
        if self.r['fenced_divs']:
            b = self.try_fenced_div()
            if b is not None:
                return b
        # blockquote
        if line.startswith('>'):
            return self.try_blockquote()
        # bullet list
        b = self.try_bullet_list()
        if b is not None:
            return b
        # ordered list
        b = self.try_ordered_list()
        if b is not None:
            return b
        # example list
        b = self.try_example_list()
        if b is not None:
            return b
        # line blocks
        if self.r['line_blocks'] and line.startswith('|'):
            return self.try_line_block()
        # header
        b = self.try_header()
        if b is not None:
            return b
        # horizontal rule
        if self.try_hr():
            return HorizontalRule()
        # indented code
        b = self.try_indented_code()
        if b is not None:
            return b
        # pipe table
        if self.r['pipe_tables']:
            b = self.try_pipe_table()
            if b is not None:
                return b
        # grid table
        if self.r['grid_tables']:
            b = self.try_grid_table()
            if b is not None:
                return b
        # simple table
        b = self.try_simple_table()
        if b is not None:
            return b
        # definition list
        b = self.try_definition_list()
        if b is not None:
            return b
        # footnote definition
        if self.try_footnote_def():
            return None
        # yaml metadata
        b = self.try_yaml_metadata()
        if b is not None:
            return b
        # title block
        b = self.try_title_block()
        if b is not None:
            return b
        # paragraph
        return self.try_paragraph()

    # ---- blank/indent helpers ----

    def indent_level(self, line):
        i = 0
        while i < len(line) and line[i] == ' ':
            i += 1
        return i

    def strip_indent(self, line, n):
        if line is None:
            return None
        i = 0
        while i < n and i < len(line) and line[i] == ' ':
            i += 1
        return line[i:]

    # ---- fenced code ----

    def try_fenced_code(self):
        line = self.cur()
        m = re.match(r'^(```+|~~~+)(.*)$', line)
        if not m:
            return None
        fence = m.group(1)
        ch = fence[0]
        info = m.group(2)
        if not self.r['fenced_code_blocks'] and ch == '`':
            pass
        if ch == '~' and not self.r['fenced_code_blocks']:
            return None
        self.pos += 1
        content = []
        attr = None
        if info.strip():
            attr = self.parse_code_attr(info)
        else:
            attr = ident()
        endpat = re.compile(r'^%s{%d,}\s*$' % (re.escape(ch), len(fence)))
        while not self.eof():
            l = self.cur()
            if endpat.match(l):
                self.pos += 1
                break
            content.append(l)
            self.pos += 1
        txt = '\n'.join(content)
        if txt:
            txt += '\n'
        return CodeBlock(attr, txt)

    def parse_code_attr(self, s):
        s = s.strip()
        if s.startswith('{') and s.endswith('}'):
            return self.parse_attr(s[1:-1])
        if s.startswith('{'):
            return self.parse_attr(s[1:])
        # language name only
        return ident(classes=[s])

    def parse_attr(self, s):
        """Parse `#id .cls k=v k2=v2` into [ident, classes, keyvals]."""
        ident_name = ''
        classes = []
        keyvals = []
        s = s.strip()
        for tok in re.findall(r'(?:#[^\s#]+|\.[^\s.]+|[^\s]+=[^\s]*|\S+)', s):
            if tok.startswith('#') and len(tok) > 1:
                ident_name = tok[1:]
            elif tok.startswith('.') and len(tok) > 1:
                classes.append(tok[1:])
            elif '=' in tok and not tok.startswith('.'):
                k, _, v = tok.partition('=')
                keyvals.append([k, self.unquote(v)])
        return [ident_name, classes, keyvals]

    def unquote(self, s):
        if len(s) >= 2 and s[0] == '"' and s[-1] == '"':
            return s[1:-1]
        return s

    # ---- fenced divs ----

    def try_fenced_div(self):
        line = self.cur()
        m = re.match(r'^(\s*)(:{3,})(.*)$', line)
        if not m:
            return None
        ind = m.group(1)
        info = m.group(3).strip()
        if info and not info.startswith('{'):
            return None
        self.pos += 1
        inner = self.parse_blocks_indented(len(ind))
        attr = self.parse_attr(info.strip()[1:-1].strip()) if info else ident()
        return Div(attr, inner)

    def parse_blocks_indented(self, n):
        saved = []
        out = []
        while not self.eof():
            l = self.cur()
            if l.strip() == '' :
                out.append(None)
                self.pos += 1
                continue
            m = re.match(r'^(%s)(:{3,})\s*(.*)$' % (' ' * n), l)
            if m:
                self.pos += 1
                break
            out.append(self.strip_indent(l, n))
            self.pos += 1
        # remove trailing Nones
        while out and out[-1] is None:
            out.pop()
        sub = '\n'.join(out) + ('\n' if out else '')
        old_lines = self.lines
        old_pos = self.pos
        self.lines = sub.split('\n')
        if self.lines and self.lines[-1] == '':
            self.lines.pop()
        self.pos = 0
        blocks = self.parse_blocks()
        self.lines = old_lines
        self.pos = old_pos
        return blocks

    # ---- blockquote ----

    def try_blockquote(self):
        self.pos += 1
        out = []
        while not self.eof():
            l = self.cur()
            if l.startswith('>'):
                out.append(l[1:].lstrip(' '))
                self.pos += 1
                continue
            if l.strip() == '':
                # lazy continuation?
                nxt = self.at(1)
                if nxt is not None and nxt.startswith('>'):
                    out.append(l)
                    self.pos += 1
                    continue
                break
            if l.strip() == '':
                break
            # lazy continuation: paragraph text after a > line
            if l and not l.startswith('>') and not l.startswith(' '):
                out.append(l)
                self.pos += 1
                continue
            break
        sub = '\n'.join(out) + ('\n' if out else '')
        old = (self.lines, self.pos)
        self.lines = sub.split('\n')
        if self.lines and self.lines[-1] == '':
            self.lines.pop()
        self.pos = 0
        blocks = self.parse_blocks()
        self.lines, self.pos = old
        return BlockQuote(blocks)

    # ---- lists ----

    def try_bullet_list(self):
        line = self.cur()
        m = re.match(r'^(\s*)([-+*])(\s+)(.*)$', line)
        if not m:
            return None
        ind = m.group(1)
        marker = m.group(2)
        if m.group(3) == '':
            return None
        items = []
        while True:
            l = self.cur()
            if l is None:
                break
            m2 = re.match(r'^(%s)([-+*])(\s+)(.*)$' % re.escape(ind), l)
            if not m2:
                break
            if m2.group(3) == '':
                break
            item_lines = [m2.group(4)]
            self.pos += 1
            # continuation
            item_lines.extend(self.lazy_continuation(ind, 2))
            # nested blocks
            blocks = self.parse_list_item(item_lines, ind, len(m2.group(3)))
            items.append(blocks)
        if not items:
            return None
        return BulletList(items)

    def lazy_continuation(self, ind, extra):
        """Collect continuation lines for a list item."""
        out = []
        while not self.eof():
            l = self.cur()
            if l is None:
                break
            if l.strip() == '':
                break
            if re.match(r'^%s([-+*])\s' % re.escape(ind), l):
                break
            m = re.match(r'^\s', l)
            if m:
                out.append(self.strip_indent(l, len(ind) + extra))
                self.pos += 1
                continue
            if l.startswith('>') or l.startswith('|') or re.match(
                    r'^\s{4,}', l):
                break
            break
        return out

    def parse_list_item(self, lines, ind, marker_indent):
        sub = '\n'.join(lines) + '\n'
        old = (self.lines, self.pos)
        self.lines = sub.split('\n')
        if self.lines and self.lines[-1] == '':
            self.lines.pop()
        self.pos = 0
        blocks = self.parse_blocks()
        self.lines, self.pos = old
        return blocks

    def try_ordered_list(self):
        line = self.cur()
        m = re.match(r'^(\s*)(\d+|[ivxlcdmIVXLCDM]+|[a-zA-Z])([.)])(\s+)(.*)$',
                     line)
        if not m:
            return None
        ind, num, delim, sp, rest = m.groups()
        if sp == '':
            return None
        style = self.list_style(num, delim)
        start = self.list_start(num)
        items = []
        while True:
            l = self.cur()
            if l is None:
                break
            m2 = re.match(r'^(%s)(\d+|[ivxlcdmIVXLCDM]+|[a-zA-Z])([.)])(\s+)(.*)$'
                          % re.escape(ind), l)
            if not m2:
                break
            if m2.group(4) == '':
                break
            if self.list_style(m2.group(2), m2.group(3)) != style:
                break
            item_lines = [m2.group(5)]
            self.pos += 1
            item_lines.extend(self.lazy_continuation(ind, 2))
            items.append(self.parse_list_item(item_lines, ind,
                                              len(m2.group(4))))
        if not items:
            return None
        return OrderedList([start, style, el(delim_delim(delim))], items)

    def list_style(self, num, delim):
        if re.match(r'^\d+$', num):
            return DECIMAL
        if re.match(r'^[ivxlcdm]+$', num):
            return LOWER_ROMAN
        if re.match(r'^[IVXLCDM]+$', num):
            return UPPER_ROMAN
        if re.match(r'^[a-z]+$', num):
            return LOWER_ALPHA
        return UPPER_ALPHA

    def list_start(self, num):
        if re.match(r'^\d+$', num):
            return int(num)
        up = num.upper()
        val = 0
        for ch in up:
            val *= 10
            val += {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500,
                    'M': 1000}.get(ch, 0)
        return val if val else 1

    def try_example_list(self):
        if not self.r['example_lists']:
            return None
        line = self.cur()
        m = re.match(r'^(\s*)@\s+(.*)$', line)
        if not m:
            return None
        return None

    def try_line_block(self):
        out = []
        while not self.eof():
            l = self.cur()
            if l.startswith('|'):
                out.append(l[1:])
                self.pos += 1
                continue
            if l.startswith(' ') and out and self.lines[self.pos - 1].startswith('|'):
                out.append(l[1:])
                self.pos += 1
                continue
            break
        lines = [[self.inlines_str(x)] for x in out]
        return LineBlock(lines)

    def inlines_str(self, s):
        return self.parse_inlines(s)

    def try_header(self):
        line = self.cur()
        if self.r['space_in_atx_header']:
            m = re.match(r'^(\s*)(#{1,6})(\s+)(.*)$', line)
        else:
            m = re.match(r'^(\s*)(#{1,6})(.*)$', line)
        if not m:
            return None
        level = len(m.group(2))
        text = m.group(4) if len(m.groups()) > 3 else m.group(3)
        # attributes at end
        attr = ident()
        m2 = re.match(r'^(.*?)\s*\{([^{}]*)\}\s*$', text)
        if m2 and self.r['header_attributes']:
            text = m2.group(1)
            attr = self.parse_attr(m2.group(2))
        self.pos += 1
        if text.strip() == '':
            return Header(level, attr, [])
        return Header(level, attr, self.parse_inlines(text))

    def try_hr(self):
        line = self.cur()
        if re.match(r'^(\s*)(\*\s*){3,}$', line) or re.match(
                r'^(\s*)(-\s*){3,}$', line) or re.match(
                r'^(\s*)(_\s*){3,}$', line):
            if self.pos > 0 and not self.blank(self.lines[self.pos - 1]):
                return False
            self.pos += 1
            return True
        return False

    def try_indented_code(self):
        line = self.cur()
        if not re.match(r'^(\s{4,}|\t)', line):
            return None
        content = []
        while not self.eof():
            l = self.cur()
            if l.strip() == '':
                # blank line: include if followed by more indented code
                nxt = self.at(1)
                if nxt is not None and re.match(r'^(\s{4,}|\t)', nxt):
                    content.append('')
                    self.pos += 1
                    continue
                break
            if not re.match(r'^(\s{4,}|\t)', l):
                break
            if len(l) >= 4:
                content.append(l[4:])
            elif l.strip() == '\t':
                content.append(l[1:])
            else:
                content.append(l)
            self.pos += 1
        if not content:
            return None
        txt = '\n'.join(content) + '\n'
        return CodeBlock(ident(), txt)

    # ---- pipe tables ----

    def try_pipe_table(self):
        head = self.cur()
        if not re.match(r'^\s*\|.*\|\s*$', head):
            return None
        sep = self.at(1)
        if sep is None:
            return None
        m = re.match(r'^\s*\|(\s*:?-+:?\s*\|)+\s*$', sep)
        if not m:
            return None
        headcells = self.split_pipe_cells(head)
        sepcells = self.parse_sep_row(sep)
        if len(headcells) != len(sepcells):
            return None
        self.pos += 2
        rows = []
        caption = [None, []]
        while not self.eof():
            l = self.cur()
            if l.strip() == '':
                break
            if not re.match(r'^\s*\|', l):
                break
            rows.append(self.split_pipe_cells(l))
            self.pos += 1
        aligns = [colspec(a, WIDTH_DEFAULT) for a in sepcells]
        return self.make_table(headcells, rows, aligns, caption)

    def split_pipe_cells(self, line):
        s = line.strip()
        if s.startswith('|'):
            s = s[1:]
        if s.endswith('|'):
            s = s[:-1]
        # split on unescaped |
        parts = re.split(r'(?<!\\)\|', s)
        return [p.strip() for p in parts]

    def parse_sep_row(self, line):
        cells = self.split_pipe_cells(line)
        out = []
        for c in cells:
            c2 = c.strip().strip('|').strip()
            a = ALIGN_DEFAULT
            if c2.startswith(':') and c2.endswith(':'):
                a = ALIGN_CENTER
            elif c2.startswith(':'):
                a = ALIGN_LEFT
            elif c2.endswith(':'):
                a = ALIGN_RIGHT
            out.append(a)
        return out

    def make_table(self, headcells, rows, aligns, caption):
        ncols = len(headcells)
        headrows = [[cell(ident(), a, 1, 1,
                          [Plain(self.parse_inlines(h))])
                     for (a, h) in zip(aligns, headcells)]]
        bodyrows = []
        for r in rows:
            cells = []
            for i in range(ncols):
                a = aligns[i][0] if i < len(aligns) else ALIGN_DEFAULT
                txt = r[i] if i < len(r) else ''
                blocks = [Plain(self.parse_inlines(txt))] if txt.strip() else []
                cells.append(cell(ident(), a, 1, 1, blocks))
            bodyrows.append(row(ident(), cells))
        return Table(ident(), caption, aligns,
                     tablehead(ident(), headrows),
                     [tablebody([], ident(), 0, bodyrows)],
                     tablebody([], ident(), [], []))

    # ---- grid tables ----

    def try_grid_table(self):
        head = self.cur()
        if not re.match(r'^\s*\+', head):
            return None
        # find separator lines
        sep_pat = re.compile(r'^\s*\+[-=:+]*\+\s*$')
        if not sep_pat.match(head):
            return None
        lines = [self.cur()]
        self.pos += 1
        header = None
        rows = []
        caption = [None, []]
        aligns = None
        while not self.eof():
            l = self.cur()
            if l.strip() == '':
                break
            lines.append(l)
            self.pos += 1
            if sep_pat.match(l):
                if aligns is None:
                    aligns = self.grid_aligns(l)
                    header = self.grid_parse_rows(lines[:-1], aligns)
                else:
                    rows.append(self.grid_parse_rows(lines[1:-1], aligns))
                lines = [l]
        if aligns is None or header is None:
            return None
        return self.make_table(header, rows, aligns, caption)

    def grid_aligns(self, sep):
        # sep looks like :------|:----:|-----:
        s = sep.strip().strip('+')
        parts = re.split(r'\+', s)
        parts = [p for p in parts if p != '']
        out = []
        for p in parts:
            p2 = p.strip()
            a = ALIGN_DEFAULT
            if p2.startswith(':') and p2.endswith(':'):
                a = ALIGN_CENTER
            elif p2.startswith(':'):
                a = ALIGN_LEFT
            elif p2.endswith(':'):
                a = ALIGN_RIGHT
            out.append(colspec(a, WIDTH_DEFAULT))
        return out

    def grid_parse_rows(self, lines, aligns):
        rows = []
        cur = None
        for l in lines:
            if l.strip().startswith('|'):
                cells = self.split_pipe_cells(l)
                if cur is None:
                    cur = [[] for _ in cells]
                else:
                    if len(cells) < len(cur):
                        cells = cells + [''] * (len(cur) - len(cells))
                    for i, c in enumerate(cells):
                        cur[i].append(c)
        if cur is not None:
            rows.append(row(ident(), [cell(ident(), a, 1, 1,
                                           [Plain(self.parse_inlines(
                                               '\n'.join(c).strip()))])
                                      for (c, a) in zip(cur, aligns)]))
        return rows

    # ---- simple/multiline tables ----

    def try_simple_table(self):
        return None

    # ---- definition lists ----

    def try_definition_list(self):
        if not self.r['definition_lists']:
            return None
        line = self.cur()
        m = re.match(r'^(\s*)(.*?)(\s*)$', line)
        if m is None:
            return None
        nxt = self.at(1)
        if nxt is None:
            return None
        if not re.match(r'^\s*:(', '', nxt):
            pass
        if not nxt.lstrip().startswith(':'):
            return None
        term = m.group(2)
        if term.strip() == '':
            return None
        items = []
        while True:
            l = self.cur()
            if l is None:
                break
            if self.blank(l):
                break
            m2 = re.match(r'^(\s*)(.*?)(\s*)$', l)
            if m2 is None:
                break
            if not self.at(1) or not self.at(1).lstrip().startswith(':'):
                break
            term = m2.group(2)
            self.pos += 1
            defs = []
            while not self.eof():
                dl = self.cur()
                if dl is None:
                    break
                if self.blank(dl):
                    nxt = self.at(1)
                    if nxt is not None and nxt.lstrip().startswith(':'):
                        break
                    defs.append('')
                    self.pos += 1
                    continue
                if dl.lstrip().startswith(':'):
                    self.pos += 1
                    dlines = [dl.lstrip()[1:].lstrip()]
                    dlines.extend(self.lazy_continuation('', 2))
                    defs.append('\n'.join(dlines))
                    continue
                break
            blocks = []
            for d in defs:
                if d == '':
                    continue
                old = (self.lines, self.pos)
                self.lines = d.split('\n')
                if self.lines and self.lines[-1] == '':
                    self.lines.pop()
                self.pos = 0
                b = self.parse_blocks()
                self.lines, self.pos = old
                blocks.append(b)
            items.append([self.parse_inlines(term), blocks])
            # continue to next term?
            if not self.eof() and not self.blank(self.cur()) and \
                    self.at(1) is not None and \
                    self.at(1).lstrip().startswith(':'):
                continue
            break
        if not items:
            return None
        return DefinitionList(items)

    def try_footnote_def(self):
        line = self.cur()
        m = re.match(r'^\s*\[\^([^\s\[\]]+)\]:\s*(.*)$', line)
        if not m or not self.r['footnotes']:
            return False
        key = m.group(1)
        self.pos += 1
        content = [m.group(2)]
        while not self.eof():
            l = self.cur()
            if l.strip() == '':
                nxt = self.at(1)
                if nxt is not None and (nxt.startswith(' ') or nxt.startswith('\t')):
                    content.append('')
                    self.pos += 1
                    continue
                break
            if l.startswith(' ') or l.startswith('\t'):
                content.append(l.lstrip())
                self.pos += 1
                continue
            break
        sub = '\n'.join(content) + '\n'
        old = (self.lines, self.pos)
        self.lines = sub.split('\n')
        if self.lines and self.lines[-1] == '':
            self.lines.pop()
        self.pos = 0
        blocks = self.parse_blocks()
        self.lines, self.pos = old
        self.footnotes[key] = blocks
        return True

    def remove_footnotes(self, blocks):
        for b in blocks:
            if isinstance(b, El):
                if b.t in ('Plain', 'Para'):
                    b.c[0] = self.expand_notes(b.c[0])
                elif b.t in ('BlockQuote', 'Div'):
                    self.remove_footnotes(b.c[1])
                elif b.t == 'BulletList':
                    for item in b.c[0]:
                        self.remove_footnotes(item)
                elif b.t == 'OrderedList':
                    for item in b.c[2]:
                        self.remove_footnotes(item)
                elif b.t == 'DefinitionList':
                    for item in b.c[0]:
                        self.remove_footnotes(item[1])

    def expand_notes(self, inlines):
        out = []
        for x in inlines:
            if isinstance(x, El) and x.t == 'NoteRef':
                blocks = self.footnotes.get(x.c[0])
                if blocks:
                    out.append(Note(blocks))
                else:
                    out.append(Str('[^' + x.c[0] + ']'))
            else:
                out.append(x)
        return out

    def try_yaml_metadata(self):
        if not self.r['yaml_metadata_block']:
            return None
        line = self.cur()
        if line.strip() != '---':
            return None
        i = self.pos + 1
        while i < len(self.lines) and self.lines[i].strip() != '---':
            i += 1
        if i >= len(self.lines):
            return None
        return None

    def try_title_block(self):
        line = self.cur()
        if not line.startswith('%'):
            return None
        if self.pos > 0 and not self.blank(self.lines[self.pos - 1]):
            return None
        return None

    def try_paragraph(self):
        lines = [self.cur()]
        self.pos += 1
        while not self.eof():
            l = self.cur()
            if l.strip() == '':
                break
            if re.match(r'^(\s*)([-+*]\s|\d+[.)]\s|[ivxlcdmIVXLCDM]+[.)]\s|'
                        r'[a-zA-Z][.)]\s|#|>|```|~~~|\|)', l):
                break
            if self.r['hard_line_breaks'] and l.startswith(' '):
                lines.append(l)
                self.pos += 1
                continue
            lines.append(l)
            self.pos += 1
        txt = '\n'.join(lines)
        return Para(self.parse_inlines(txt))

    # ---------------- inline parsing ----------------

    def parse_inlines(self, s):
        p = InlineParser(self, s)
        return p.parse()


def delim_delim(d):
    return {'': '', '.': 'Period', ')': 'OneParen'}[d]
