                    out.append(LineBreak())
                else:
                    out.append(SoftBreak())
                self.i += 1
                continue
            if self.md is not None and self.md.r['smart']:
                r = self.smart()
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
            self.buf += c
            self.i += 1
