        return out

    def flush(self, out):
        if self.buf:
            out.append(Str(self.buf))
            self.buf = ''

    def attr_after_text(self):
        return False

    # ---- escape ----

    def escape(self):
        md = self.md
        s = self.s
        i = self.i
        if i + 1 >= len(s):
            return None
        c = s[i + 1]
        if c == '\n':
            if md is None or md.r['escaped_line_breaks']:
                self.i += 2
                return LineBreak()
            return None
        if c == ' ':
            self.i += 2
            return Str(NBSP)
        if c == '\t':
            self.i += 2
            return Str(NBSP)
        if c.isalpha():
            # TeX command
            if md is None or md.r['raw_tex']:
                m = re.match(r'\\[a-zA-Z]+(\*|@)?(\s*\{[^{}]*\}|\s+)*', s[i:])
                if m:
                    self.i += m.end()
                    return RawInline('tex', m.group(0).rstrip())
                m = re.match(r'\\[a-zA-Z]+\*', s[i:])
                if m:
                    self.i += m.end()
                    return RawInline('tex', m.group(0))
