    # ---- code span ----

    def code_span(self):
        s = self.s
        i = self.i
        m = re.match(r'`+', s[i:])
        if not m:
            return None
        n = len(m.group(0))
        j = i + n
        while True:
            m2 = re.compile('`{%d}' % n).search(s, j)
            if m2 is None:
                return None
            # must not be followed by a backtick
            if s[m2.start():].startswith('`') and \
                    j + 1 < len(s) and s[m2.end():m2.end() + 1] == '`':
                j = m2.end() + 1
                continue
            break
        content = s[i + n:m2.start()]
        if content.startswith(' ') and content.endswith(' ') and len(content) > 1:
            content = content[1:-1]
        self.i = m2.end()
        attr = None
        if self.s[self.i:self.i + 1] == '{' and \
                self.md is not None and self.md.r['inline_code_attributes']:
            m3 = re.match(r'\{([^{}]*)\}', s[self.i:])
            if m3:
                attr = parse_attr_string(m3.group(1))
                self.i += m3.end()
        return Code(attr if attr is not None else ident(), content)

    # ---- emphasis ----

    def emph_or_strong(self, c):
        s = self.s
        i = self.i
        n = 0
        while i + n < len(s) and s[i + n] == c:
            n += 1
        if n >= 3:
            n = 2 if n == 3 else n
        if n >= 2:
            # strong
            j = self.find_close(c, i + n, 2)
            if j is not None:
                inner = s[i + n:j]
                self.i = j + 2
                return Strong(self.sub(inner))
        if n == 1 or n >= 2:
            j = self.find_close(c, i + n, 1)
            if j is not None:
                inner = s[i + 1:j]
                self.i = j + 1
                return Emph(self.sub(inner))
        return None

    def find_close(self, c, start, n):
        """Find n consecutive c at position >= start, respecting nesting."""
        s = self.s
        i = start
        while i < len(s):
            if s[i] == '\\':
                i += 2
                continue
            if s[i] == c:
                k = 0
                while i + k < len(s) and s[i + k] == c:
                    k += 1
                if k >= n:
                    return i
                i += k
                continue
            i += 1
        return None

    def sub(self, s):
        p = InlineParser(self.md, s, self.pos)
        return p.parse()

    # ---- strikeout / subscript ----

    def strike_or_sub(self):
        s = self.s
        i = self.i
        if s[i:i + 2] == '~~' and self.md is not None and \
                self.md.r['strikeout']:
            j = self.find_close('~', i + 2, 2)
            if j is not None:
                inner = s[i + 2:j]
                self.i = j + 2
                return Strikeout(self.sub(inner))
            return None
        # subscript ~x~
        if self.md is None or self.md.r['subscript']:
            if i + 1 < len(s) and s[i + 1] not in ' \t\n' and \
                    s[i + 1] != '~':
                j = self.find_close('~', i + 1, 1)
                if j is not None and j > i + 1:
                    inner = s[i + 1:j]
                    if inner.strip():
                        self.i = j + 1
                        return Subscript(self.sub(inner))
        return None

    def super_or_note(self):
        s = self.s
        i = self.i
        if self.md is not None and self.md.r['inline_notes'] and \
                s[i:i + 2] == '^[':
            j = self.match_bracket(s, i + 1)
            if j is not None:
                inner = s[i + 2:j]
                self.i = j + 1
                sub = '\n'.join(x.strip() for x in inner.split('\n'))
                blocks = [Para(self.sub(sub))] if inner.strip() else []
                return Note(blocks)
        if self.md is None or self.md.r['superscript']:
            if i + 1 < len(s) and s[i + 1] not in ' \t\n':
                j = self.find_close('^', i + 1, 1)
                if j is not None and j > i + 1:
                    inner = s[i + 1:j]
                    if inner.strip():
                        self.i = j + 1
                        return Superscript(self.sub(inner))
        return None

    # ---- math ----

    def math(self):
        s = self.s
        i = self.i
        md = self.md
        if md is None or not md.r['tex_math_dollars']:
            return None
        if s[i:i + 2] == '$$':
            j = self.find_close('$', i + 2, 2)
            if j is not None:
                inner = s[i + 2:j]
                self.i = j + 2
                return Math(DISPLAY_MATH, inner)
        # single $
        m = re.compile(r'\$([^$\n]*[^$\n\\])\$').match(s, i)
        if m:
            inner = m.group(1)
            self.i = m.end()
            return Math(INLINE_MATH, inner)
        return None

    # ---- smart punctuation ----

    def smart(self):
        s = self.s
        i = self.i
        c = s[i]
        if s[i:i + 3] == '---':
            self.i += 3
            return Str('\u2014')
        if s[i:i + 2] == '--':
            self.i += 2
            return Str('\u2013')
        if s[i:i + 3] == '...':
            self.i += 3
            return Str('\u2026')
        if s[i:i + 2] == '. . .':
            self.i += 5
            return Str('\u2026')
        if c == '"':
            return self.quoted('"')
        if c == "'":
            return self.quoted("'")
        if s[i:i + 2] == '<<':
            self.i += 2
            return Str('\u00ab')
        if s[i:i + 2] == '>>':
            self.i += 2
            return Str('\u00bb')
        return None

    def quoted(self, q):
        s = self.s
        i = self.i
        if q == '"':
            m = re.match(r'"([^"]*)"', s[i:])
            if m:
                self.i += m.end()
                return Quoted(DOUBLE_QUOTE, self.sub(m.group(1)))
        else:
            m = re.match(r"'([^']*)'", s[i:])
            if m:
                self.i += m.end()
                return Quoted(SINGLE_QUOTE, self.sub(m.group(1)))
        return None

    # ---- bracket: link, image, reference, span, footnote, citation ----

    def bracket(self, image=False):
        s = self.s
        i = self.i
        j = self.match_bracket(s, i + 1)
        if j is None:
            return None
        label = s[i + 1:j]
        k = j + 1
        md = self.md
        if s[k:k + 1] == '(':
            m = re.match(r'\(([^()]*)(?:\s+"([^"]*)")?\)', s[k:])
            if m:
                url = m.group(1).strip()
                title = m.group(2) or ''
                self.i = k + m.end()
                attr = None
                if s[self.i:self.i + 1] == '{' and md is not None and \
                        md.r['link_attributes']:
                    m3 = re.match(r'\{([^{}]*)\}', s[self.i:])
                    if m3:
                        attr = parse_attr_string(m3.group(1))
                        self.i += m3.end()
                if image:
                    if not url.endswith(('.png', '.jpg', '.jpeg', '.gif',
                                         '.webp', '.svg', '.eps', '.pdf')):
                        ext = 'jpg'
                        url = url + '.jpg' if '.' not in url else url
                    return Image(attr if attr is not None else ident(),
                                 self.sub(label), [url, title])
                return Link(attr if attr is not None else ident(),
                            self.sub(label), [url, title])
        if s[k:k + 1] == '[':
            m = re.match(r'\[([^\[\]]*)\]', s[k:])
            if m:
                ref = m.group(1)
                self.i = k + m.end()
                return self.reference(label, ref, image)
        # implicit reference
        if not image and md is not None and md.r['shortcut_reference_links'] \
                and label in self.refs:
            return self.reference(label, label, image)
        if not image and md is not None and md.r['implicit_figures'] \
                and image:
            pass
        return None

    def reference(self, label, ref, image=False):
        md = self.md
        key = ref.strip()
        if key not in self.refs:
            return None
        url, title = self.refs[key]
        attr = ident()
        if md is not None and md.r['reference_links']:
            pass
        if image:
            return Image(attr, self.sub(label), [url, title])
        return Link(attr, self.sub(label), [url, title])

    def match_bracket(self, s, start):
        """Find the matching ] for the [ at start-1; returns index of ]."""
        depth = 1
        i = start
        while i < len(s):
            c = s[i]
            if c == '\\':
                i += 2
                continue
            if c == '`':
                m = re.match(r'`+', s[i:])
                i += len(m.group(0))
                continue
            if c == '[':
                depth += 1
            elif c == ']':
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return None

    # ---- < autolinks, raw html ----

    def lt(self):
        s = self.s
        i = self.i
        md = self.md
        m = re.match(r'<([a-zA-Z][a-zA-Z0-9+.-]*://[^<>\s]*)>', s[i:])
        if m:
            self.i += m.end()
            return Link(ident(classes=['uri']), [Str(m.group(1))],
                        [m.group(1), ''])
        m = re.match(r'<([a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+)>', s[i:])
        if m:
            self.i += m.end()
            return Link(ident(classes=['mailto']),
                        [Str(m.group(1))], ['mailto:' + m.group(1), ''])
        if md is None or not md.r['raw_html']:
            return None
        m = re.match(r'<[^<>\n]*>', s[i:])
        if m:
            self.i += m.end()
            return RawInline('html', m.group(0))
        return None

    # ---- citations ----

    def citation(self):
        s = self.s
        i = self.i
        m = re.match(r'@([a-zA-Z0-9_.:+\-/#]+)', s[i:])
        if not m:
            return None
        self.i += m.end()
        key = m.group(1)
        md = self.md
        if md is None:
            return None
        cite = citation(key, [], [], AUTHOR_IN_TEXT, 1, 0)
        return Cite([cite], [Str('@' + key)])
