"""Markdown reader (pandoc's Markdown flavour)."""
import re

from .ast import (El, el, Doc, Str, Space, Para, Plain, Header, CodeBlock,
                  BlockQuote, BulletList, OrderedList, DefinitionList,
                  HorizontalRule, Div, Figure, LineBlock, RawBlock, Table,
                  ALIGN_DEFAULT, ident, row, cell, colspec, tablehead,
                  tablebody, caption, citation, DECIMAL, LOWER_ALPHA,
                  UPPER_ALPHA, LOWER_ROMAN, UPPER_ROMAN, INLINE_MATH,
                  DISPLAY_MATH, SINGLE_QUOTE, DOUBLE_QUOTE, NORMAL_CITE,
                  AUTHOR_IN_TEXT, SUPPRESS_CITE, Math, Code, Emph, Strong,
                  Strikeout, Superscript, Subscript, Underline, SmallCaps,
                  Quoted, Link, Image, Span, Note, Cite, LineBreak, SoftBreak,
                  RawInline, Period, OneParen)


NBSP = '\xa0'

ROMAN = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}


def load_default_exts(fmt):
    from . import data as datamod
    exts = set()
    for line in datamod.lines('extensions/%s.txt' % fmt):
        if not line:
            continue
        if line.startswith('+'):
            exts.add(line[1:])
        elif line.startswith('-'):
            exts.discard(line[1:])
    return exts


def parse_ext_spec(spec):
    if spec is None:
        return None, []
    parts = spec.split('+')
    fmt = parts[0]
    exts = []
    for p in parts[1:]:
        if p.startswith('-'):
            exts.append((p[1:], False))
        else:
            exts.append((p, True))
    return fmt, exts


def parse_format(spec, known, is_reader):
    fmt, exts = parse_ext_spec(spec)
    if fmt in ('markdown_github', 'markdown_github'):
        fmt = 'markdown_github'
    return fmt, exts


class Reader:
    name = 'markdown'

    def __init__(self, fmt, opt_exts=None):
        base = fmt
        if fmt.startswith('markdown'):
            base = 'markdown'
        elif fmt in ('commonmark_x', 'commonmark', 'gfm', 'markdown_github'):
            base = fmt
        self.base = base
        self.exts = load_default_exts(fmt)
        if opt_exts:
            for e, val in opt_exts:
                if val:
                    self.exts.add(e)
                else:
                    self.exts.discard(e)

    def __getitem__(self, name):
        return name in self.exts


# ---------------- attributes ----------------

def parse_attr_string(s):
    """Parse "#id .cls k=v k2=v2" into [ident, classes, keyvals]."""
    s = s.strip()
    ident_name = ''
    classes = []
    keyvals = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '#':
            m = re.match(r'[^\s]+', s[i + 1:])
            if m:
                ident_name = m.group(0)
                i += 1 + len(m.group(0))
                continue
        if c == '.':
            m = re.match(r'[^\s]+', s[i + 1:])
            if m:
                classes.append(m.group(0))
                i += 1 + len(m.group(0))
                continue
        m = re.match(r'[^\s]+', s[i:])
        if m:
            tok = m.group(0)
            i += len(tok)
            if '=' in tok:
                k, _, v = tok.partition('=')
                keyvals.append([k, unquote_attr(v)])
            elif c == '=' or tok.startswith('='):
                pass
            else:
                classes.append(tok) if False else None
            continue
        i += 1
    return [ident_name, classes, keyvals]


def unquote_attr(s):
    if len(s) >= 2 and s[0] == '"' and s[-1] == '"':
        return s[1:-1]
    return s


# ---------------- title / yaml metadata ----------------

def yaml_to_meta(text, md=None):
    """Very small YAML subset parser for pandoc metadata."""
    from .ast import El
    meta = {}
    lines = text.split('\n')
    i = 0
    cur = None
    while i < len(lines):
        l = lines[i]
        if not l.strip() or l.strip().startswith('#'):
            i += 1
            continue
        m = re.match(r'^([A-Za-z0-9_-]+)\s*:\s*(.*)$', l)
        if m:
            key = m.group(1)
            val = m.group(2).strip()
            if val == '':
                # nested block or list
                items = []
                i += 1
                while i < len(lines):
                    l2 = lines[i]
                    m2 = re.match(r'^\s+-\s+(.*)$', l2)
                    m3 = re.match(r'^([A-Za-z0-9_-]+)\s*:\s*(.*)$', l2)
                    if m2:
                        items.append(m2.group(1).strip())
                        i += 1
                    elif l2.strip() == '':
                        break
                    else:
                        break
                if items:
                    meta[key] = El('MetaList', [[El('MetaInlines',
                                                   [Str(x)]) for x in items]])
                else:
                    meta[key] = El('MetaInlines', [Str('')])
                continue
            if val.startswith('[') and val.endswith(']'):
                inner = val[1:-1].strip()
                items = [x.strip().strip('"').strip("'")
                         for x in split_yaml_items(inner)] if inner else []
                meta[key] = El('MetaList',
                               [[El('MetaInlines', [Str(x)]) for x in items]])
            elif val in ('true', 'false'):
                meta[key] = El('MetaBool', [val == 'true'])
            elif val.startswith('"') and val.endswith('"'):
                meta[key] = El('MetaInlines', [Str(val[1:-1])])
            else:
                meta[key] = El('MetaInlines', parse_meta_inlines(val))
        i += 1
    return meta


def split_yaml_items(s):
    out = []
    cur = ''
    depth = 0
    for ch in s:
        if ch == '[':
            depth += 1
        elif ch == ']':
            depth -= 1
        if ch == ',' and depth == 0:
            out.append(cur)
            cur = ''
            continue
        cur += ch
    if cur.strip():
        out.append(cur)
    return out


def parse_meta_inlines(s):
    """Parse markdown inlines for metadata (limited)."""
    p = InlineParser(None, s, None)
    return p.parse()


# ---------------- inline parser ----------------

class InlineParser:
    def __init__(self, md, s, pos=None, sp=None):
        self.md = md
        self.s = s
        self.i = 0
        self.pos = pos
        self.sp = sp if sp is not None else (0, 0)
        self.buf = ''
        self.refs = {} if md is None else md.refs
        self.notenums = {} if md is None else md.notenums

    def parse(self):
        out = []
        while self.i < len(self.s):
            c = self.s[self.i]
            if c == '\\':
                r = self.escape()
                if r is None:
                    self.buf += c
                    self.i += 1
                else:
                    self.flush(out)
                    out.extend(r if isinstance(r, list) else [r])
                continue
            if c == '`':
                r = self.code_span()
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
                self.buf += c
                self.i += 1
                continue
            if c in '*_':
                r = self.emph_or_strong(c)
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
                self.buf += c
                self.i += 1
                continue
            if c == '~':
                r = self.strike_or_sub()
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
                self.buf += c
                self.i += 1
                continue
            if c == '^':
                r = self.super_or_note()
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
                self.buf += c
                self.i += 1
                continue
            if c == '$':
                r = self.math()
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
                self.buf += c
                self.i += 1
                continue
            if c == '[':
                r = self.bracket()
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
                self.buf += c
                self.i += 1
                continue
            if c == '!' and self.i + 1 < len(self.s) and \
                    self.s[self.i + 1] == '[':
                r = self.bracket(image=True)
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
                self.buf += c
                self.i += 1
                continue
            if c == '<':
                r = self.lt()
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
                self.buf += c
                self.i += 1
                continue
            if c == '@' and self.md is not None and self.md.r['citations']:
                r = self.citation()
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
                self.buf += c
                self.i += 1
                continue
            if c == '{' and self.buf and self.attr_after_text():
                pass
            if c in ' \t':
                if self.buf.endswith(' ') or self.buf.endswith(NBSP):
                    pass
                else:
                    self.flush(out)
                    out.append(Space())
                self.i += 1
                continue
            if c == '\n':
                self.flush(out)
                if self.md is not None and self.md.r['hard_line_breaks']:
                    out.append(LineBreak())
                else:
                    out.append(SoftBreak())
                self.i += 1
                continue
            if self.md is not None and self.md.r['smart']:
                r = self.smart()
                if r is not None:
                    self.flush(out)
                    out.append(r)
                    continue
            self.buf += c
            self.i += 1
        self.flush(out)
        return out

    def flush(self, out):
        if self.buf:
            out.append(Str(self.buf))
            self.buf = ''

    def attr_after_text(self):
        return False

    # ---- escape ----

    def escape(self):
        md = self.md
        s = self.s
        i = self.i
        if i + 1 >= len(s):
            return None
        c = s[i + 1]
        if c == '\n':
            if md is None or md.r['escaped_line_breaks']:
                self.i += 2
                return LineBreak()
            return None
        if c == ' ':
            self.i += 2
            return Str(NBSP)
        if c == '\t':
            self.i += 2
            return Str(NBSP)
        if c.isalpha():
            # TeX command
            if md is None or md.r['raw_tex']:
                m = re.match(r'\\[a-zA-Z]+(\*|@)?(\s*\{[^{}]*\}|\s+)*', s[i:])
                if m:
                    self.i += m.end()
                    return RawInline('tex', m.group(0).rstrip())
                m = re.match(r'\\[a-zA-Z]+\*', s[i:])
                if m:
                    self.i += m.end()
                    return RawInline('tex', m.group(0))
            self.i += 2
            return Str(c)
        if md is None or (md.r['all_symbols_escapable'] or
                          c in '`*_{}[]()>#+-.!:|"\')'):
            self.i += 2
            return Str(c)
        return None

    # ---- code span ----

    def code_span(self):
        s = self.s
        i = self.i
        m = re.match(r'`+', s[i:])
        if not m:
            return None
        n = len(m.group(0))
        j = i + n
        while True:
            m2 = re.compile('`{%d}' % n).search(s, j)
            if m2 is None:
                return None
            # must not be followed by a backtick
            if s[m2.start():].startswith('`') and \
                    j + 1 < len(s) and s[m2.end():m2.end() + 1] == '`':
                j = m2.end() + 1
                continue
            break
        content = s[i + n:m2.start()]
        if content.startswith(' ') and content.endswith(' ') and len(content) > 1:
            content = content[1:-1]
        self.i = m2.end()
        attr = None
        if self.s[self.i:self.i + 1] == '{' and \
                self.md is not None and self.md.r['inline_code_attributes']:
            m3 = re.match(r'\{([^{}]*)\}', s[self.i:])
            if m3:
                attr = parse_attr_string(m3.group(1))
                self.i += m3.end()
        return Code(attr if attr is not None else ident(), content)

    # ---- emphasis ----

    def emph_or_strong(self, c):
        s = self.s
        i = self.i
        n = 0
        while i + n < len(s) and s[i + n] == c:
            n += 1
        if n >= 3:
            n = 2 if n == 3 else n
        if n >= 2:
            # strong
            j = self.find_close(c, i + n, 2)
            if j is not None:
                inner = s[i + n:j]
                self.i = j + 2
                return Strong(self.sub(inner))
        if n == 1 or n >= 2:
            j = self.find_close(c, i + n, 1)
            if j is not None:
                inner = s[i + 1:j]
                self.i = j + 1
                return Emph(self.sub(inner))
        return None

    def find_close(self, c, start, n):
        """Find n consecutive c at position >= start, respecting nesting."""
        s = self.s
        i = start
        while i < len(s):
            if s[i] == '\\':
                i += 2
                continue
            if s[i] == c:
                k = 0
                while i + k < len(s) and s[i + k] == c:
                    k += 1
                if k >= n:
                    return i
                i += k
                continue
            i += 1
        return None

    def sub(self, s):
        p = InlineParser(self.md, s, self.pos)
        return p.parse()

    # ---- strikeout / subscript ----

    def strike_or_sub(self):
        s = self.s
        i = self.i
        if s[i:i + 2] == '~~' and self.md is not None and \
                self.md.r['strikeout']:
            j = self.find_close('~', i + 2, 2)
            if j is not None:
                inner = s[i + 2:j]
                self.i = j + 2
                return Strikeout(self.sub(inner))
            return None
        # subscript ~x~
        if self.md is None or self.md.r['subscript']:
            if i + 1 < len(s) and s[i + 1] not in ' \t\n' and \
                    s[i + 1] != '~':
                j = self.find_close('~', i + 1, 1)
                if j is not None and j > i + 1:
                    inner = s[i + 1:j]
                    if inner.strip():
                        self.i = j + 1
                        return Subscript(self.sub(inner))
        return None

    def super_or_note(self):
        s = self.s
        i = self.i
        if self.md is not None and self.md.r['inline_notes'] and \
                s[i:i + 2] == '^[':
            j = self.match_bracket(s, i + 1)
            if j is not None:
                inner = s[i + 2:j]
                self.i = j + 1
                sub = '\n'.join(x.strip() for x in inner.split('\n'))
                blocks = [Para(self.sub(sub))] if inner.strip() else []
                return Note(blocks)
        if self.md is None or self.md.r['superscript']:
            if i + 1 < len(s) and s[i + 1] not in ' \t\n':
                j = self.find_close('^', i + 1, 1)
                if j is not None and j > i + 1:
                    inner = s[i + 1:j]
                    if inner.strip():
                        self.i = j + 1
                        return Superscript(self.sub(inner))
        return None

    # ---- math ----

    def math(self):
        s = self.s
        i = self.i
        md = self.md
        if md is None or not md.r['tex_math_dollars']:
            return None
        if s[i:i + 2] == '$$':
            j = self.find_close('$', i + 2, 2)
            if j is not None:
                inner = s[i + 2:j]
                self.i = j + 2
                return Math(DISPLAY_MATH, inner)
        # single $
        m = re.compile(r'\$([^$\n]*[^$\n\\])\$').match(s, i)
        if m:
            inner = m.group(1)
            self.i = m.end()
            return Math(INLINE_MATH, inner)
