def load_default_exts(fmt):
    from . import data as datamod
    exts = set()
    for line in datamod.lines('extensions/%s.txt' % fmt):
        if not line:
            continue
        if line.startswith('+'):
            exts.add(line[1:])
        elif line.startswith('-'):
            exts.discard(line[1:])
    return exts


def parse_ext_spec(spec):
    if spec is None:
        return None, []
    parts = spec.split('+')
    fmt = parts[0]
    exts = []
    for p in parts[1:]:
        if p.startswith('-'):
            exts.append((p[1:], False))
        else:
            exts.append((p, True))
    return fmt, exts


