# ============================ block parsing ============================

BLOCK_TAGS = {'address', 'article', 'aside', 'blockquote', 'body', 'canvas',
              'caption', 'center', 'col', 'colgroup', 'dd', 'details', 'div',
              'dl', 'dt', 'fieldset', 'figcaption', 'figure', 'footer', 'form',
              'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'header', 'hr', 'html',
              'legend', 'li', 'main', 'menu', 'nav', 'ol', 'optgroup',
              'option', 'p', 'pre', 'script', 'section', 'select', 'style',
              'summary', 'table', 'tbody', 'td', 'tfoot', 'th', 'thead',
              'tr', 'ul', 'video', 'audio', 'br', 'comment', '!--'}


class MdParser:
    def __init__(self, reader, opts=None, source=None):
        self.r = reader
        self.opts = opts
        self.meta = {}
        self.refs = {}
        self.notenums = {}
        self.footnotes = {}
        self.source = source

    def parse(self, text):
        self.lines = text.replace('\r\n', '\n').split('\n')
        if self.lines and self.lines[-1] == '':
            self.lines.pop()
        self.pos = 0
        blocks = self.parse_blocks()
        self.resolve_notes(blocks)
        return Doc(self.meta, blocks)

    def cur(self):
        return self.lines[self.pos] if self.pos < len(self.lines) else None

    def at(self, i):
        p = self.pos + i
        return self.lines[p] if p < len(self.lines) else None

    def eof(self):
        return self.pos >= len(self.lines)

    def blank(self, line):
        return line is not None and line.strip() == ''

    def indent(self, line):
        return len(line) - len(line.lstrip(' \t'))

    # ---------------- top-level ----------------

    def parse_blocks(self):
        out = []
        while not self.eof():
            n = self.pos
            b = self.parse_block()
            if b is not None:
                out.extend(b if isinstance(b, list) else [b])
            if self.pos == n:
                self.pos += 1
        return out

    def parse_block(self):
        line = self.cur()
        if self.blank(line):
            self.pos += 1
            return None
        # yaml metadata block
        if self.r['yaml_metadata_block'] and line.strip() == '---':
            if self.try_yaml_metadata():
                return None
        # fenced code
        m = re.match(r'^(\s*)(```+|~~~+)(.*)$', line)
        if m and not m.group(2).startswith('~~~') or (m and m.group(2)[0] == '~'):
            if m:
                if self.r['fenced_code_blocks']:
                    return self.parse_fenced_code(m)
                if m.group(2)[0] == '~' and False:
                    pass
        if self.r['fenced_divs']:
            m2 = re.match(r'^(\s*)(:{3,})(.*)$', line)
            if m2 and (not m2.group(3).strip() or
                       m2.group(3).strip().startswith('{')):
                return self.parse_fenced_div(m2)
        # raw block ```=
        m3 = re.match(r'^(\s*)(`{3,}|~{3,})\s*\{=(\w+)\}\s*$', line)
        if m3 and self.r['raw_attribute']:
            return self.parse_raw_block(m3)
        # blockquote
        if re.match(r'^\s*>', line):
            return self.parse_blockquote()
        # bullet list
        if re.match(r'^\s*[-*]\s+', line) and self.r['fancy_lists']:
            b = self.parse_bullet_list()
            if b is not None:
                return b
        elif re.match(r'^\s*-\s+', line):
            b = self.parse_bullet_list()
            if b is not None:
                return b
        # ordered list
        if re.match(r'^\s*(\d+|[ivxlcdmIVXLCDM]+|[a-zA-Z])[.)]\s+', line):
            b = self.parse_ordered_list()
            if b is not None:
                return b
        # line block
        if self.r['line_blocks'] and re.match(r'^\s*\|', line):
            return self.parse_line_block()
        # header
        if re.match(r'^\s*#{1,6}(\s|$)', line):
            return self.parse_atx_header()
        # horizontal rule
        if re.match(r'^\s*([-*_=])(\s*\1){2,}\s*$', line):
            self.pos += 1
            return HorizontalRule()
        # indented code (only at top level of a block context)
        if re.match(r'^(\s{4,}|\t)\S', line):
            return self.parse_indented_code()
        # html block
        if self.r['raw_html']:
            m4 = re.match(r'^\s*<([a-zA-Z][a-zA-Z0-9]*)', line)
            if m4 and m4.group(1).lower() in BLOCK_TAGS:
                return self.parse_html_block(m4.group(1).lower())
            if re.match(r'^\s*<!--', line):
                return self.parse_comment_block()
        # pipe table
        if self.r['pipe_tables'] and re.match(r'^\s*\|', line):
            t = self.try_pipe_table()
            if t is not None:
                return t
        # grid table
        if self.r['grid_tables'] and re.match(r'^\s*\+', line):
            t = self.try_grid_table()
            if t is not None:
                return t
        # footnote definition
        if self.r['footnotes']:
            m5 = re.match(r'^\s*\[\^([^\s\[\]]+)\]:\s*(.*)$', line)
            if m5:
                self.parse_footnote_def(m5.group(1), m5.group(2))
                return None
        # link reference definition
        m6 = re.match(r'^\s*\[([^\]]+)\]:\s*(.*)$', line)
        if m6:
            self.parse_link_def(m6.group(1), m6.group(2))
            return None
        # title block
        if self.r['pandoc_title_block'] and line.startswith('%'):
            if self.pos == 0 or self.blank(self.at(-1)):
                self.parse_title_block()
                return None
        # paragraph / definition list
        return self.parse_paragraph()

    # ---------------- paragraphs ----------------

    def parse_paragraph(self):
        lines = [self.cur()]
        self.pos += 1
        while not self.eof():
            l = self.cur()
            if self.blank(l):
                break
            m = re.match(r'^(\s*)(```+|~~~+)(.*)$', l)
            if m:
                break
            m4 = re.match(r'^\s*<([a-zA-Z][a-zA-Z0-9]*)', l)
            if m4 and m4.group(1).lower() in BLOCK_TAGS:
                break
            if re.match(r'^\s*<!--', l):
                break
            if self.r['definition_lists'] and len(lines) == 1 and \
                    re.match(r'^\s*:\s', l):
                return self.parse_definition_list(lines[0])
            lines.append(l)
            self.pos += 1
        # setext header?
        l = self.cur()
        if l is not None and len(lines) >= 1:
            m = re.match(r'^\s*(=+)\s*$', l)
            m2 = re.match(r'^\s*(-+)\s*$', l)
            if m or m2:
                if self.pos == 0 or not self.blank(self.at(-1)):
                    level = 1 if m else 2
                    self.pos += 1
                    text = '\n'.join(lines)
                    text = self.strip_indent_all(text, 0)
                    attr = ident()
                    m3 = re.match(r'^(.*)\{([^{}]*)\}\s*$', text)
                    if m3 and self.r['header_attributes'] and \
                            m3.group(2).strip():
                        text = m3.group(1)
                        attr = parse_attr_string(m3.group(2))
                    return Header(level, attr, self.inl(text.strip()))
        return Para(self.inl('\n'.join(lines)))

    def strip_indent_all(self, text, n):
        return text

    # ---------------- headers ----------------

    def parse_atx_header(self):
        line = self.cur()
        m = re.match(r'^(\s*)(#{1,6})(\s+)(.*)$', line)
        if not m:
            m = re.match(r'^(\s*)(#{1,6})\s*$', line)
            if not m:
                return Para(self.inl(line))
            level = len(m.group(2))
            self.pos += 1
            return Header(level, ident(), [])
        level = len(m.group(2))
        text = m.group(4)
        self.pos += 1
        attr = ident()
        m3 = re.match(r'^(.*?)\s*\{([^{}]*)\}\s*$', text)
        if m3 and self.r['header_attributes'] and m3.group(2).strip():
            text = m3.group(1)
            attr = parse_attr_string(m3.group(2))
        return Header(level, attr, self.inl(text))

    # ---------------- fenced code ----------------

    def parse_fenced_code(self, m):
        ind = m.group(1)
        fence = m.group(2)
        ch = fence[0]
        info = m.group(3)
        self.pos += 1
        content = []
        attr = ident()
        if info.strip():
            mi = re.match(r'^\s*\{([^{}]*)\}\s*$', info)
            if mi:
                attr = parse_attr_string(mi.group(1))
            else:
                attr = ident(classes=[info.strip()])
        else:
            attr = ident(classes=[]) if not info.strip() else \
                ident(classes=[info.strip()])
        endpat = re.compile(r'^(\s*)%s{%d,}\s*$' % (re.escape(ch), len(fence)))
        while not self.eof():
            l = self.cur()
            if endpat.match(l):
                self.pos += 1
                break
            content.append(self.strip_indent(l, len(ind)))
            self.pos += 1
        txt = '\n'.join(content)
        if txt:
            txt += '\n'
        return CodeBlock(attr, txt)

    def parse_raw_block(self, m):
        ind = m.group(1)
        fence = m.group(2)
        fmt = m.group(3)
        self.pos += 1
        content = []
        endpat = re.compile(r'^(\s*)%s{%d,}\s*$' % (re.escape(fence[0]),
                                                    len(fence)))
        while not self.eof():
            l = self.cur()
            if endpat.match(l):
                self.pos += 1
                break
            content.append(self.strip_indent(l, len(ind)))
            self.pos += 1
        txt = '\n'.join(content)
        if txt:
            txt += '\n'
        return RawBlock(fmt, txt.rstrip('\n'))

    def strip_indent(self, line, n):
        i = 0
        while i < n and i < len(line) and line[i] in ' \t':
            i += 1
        return line[i:]

    # ---------------- fenced divs ----------------

    def parse_fenced_div(self, m):
        ind = m.group(1)
        info = m.group(3).strip()
        self.pos += 1
        inner = []
        endpat = re.compile(r'^(%s):{3,}\s*$' % re.escape(' ' * len(ind)))
        while not self.eof():
            l = self.cur()
            if re.match(r'^%s(:{3,})\s*$' % re.escape(' ' * len(ind)), l):
                self.pos += 1
                break
            if self.blank(l):
                inner.append(None)
                self.pos += 1
                continue
            inner.append(self.strip_indent(l, len(ind)))
            self.pos += 1
        while inner and inner[-1] is None:
            inner.pop()
        blocks = self.parse_sub('\n'.join(x if x is not None else ''
                                          for x in inner))
        attr = parse_attr_string(info[1:-1].strip()) if info else ident()
        return Div(attr, blocks)

    def parse_sub(self, text):
        """Parse a sub-document, restoring state afterwards."""
        old = (self.lines, self.pos)
        self.lines = text.split('\n')
        if self.lines and self.lines[-1] == '':
            self.lines.pop()
        self.pos = 0
        blocks = self.parse_blocks()
        self.lines, self.pos = old
        return blocks

    # ---------------- blockquote ----------------

    def parse_blockquote(self):
        out = []
        while not self.eof():
            l = self.cur()
            if l.strip() == '':
                nxt = self.at(1)
                if nxt is not None and re.match(r'^\s*>', nxt):
                    out.append(None)
                    self.pos += 1
                    continue
                break
            if re.match(r'^\s*>', l):
                m = re.match(r'^\s*>(.*)$', l)
                out.append(m.group(1))
                self.pos += 1
                continue
            # lazy continuation
            out.append(l)
            self.pos += 1
        text = '\n'.join(x if x is not None else '' for x in out)
        return BlockQuote(self.parse_sub(text))

    # ---------------- lists ----------------

    def parse_bullet_list(self):
        line = self.cur()
        m = re.match(r'^(\s*)([-*])(\s+)(.*)$', line)
        if not m:
            return None
        ind, marker, sp, rest = m.groups()
        items = []
        pending_blank = False
        while not self.eof():
            l = self.cur()
            if l is None:
                break
            if self.blank(l):
                nxt = self.at(1)
                if nxt is not None and re.match(r'^%s%s\s+' % (re.escape(ind),
                                                               marker), nxt):
                    pending_blank = True
                    self.pos += 1
                    continue
                break
            m2 = re.match(r'^(%s)([-*])(\s+)(.*)$' % re.escape(ind), l)
            if not m2:
                break
            if m2.group(2) != marker:
                break
            items.append(self.parse_list_item(ind, len(sp), m2.group(4),
                                              pending_blank))
            pending_blank = False
        if not items:
            return None
        return BulletList(items)

    def parse_list_item(self, ind, sp, first, had_blank):
        self.pos += 1
        # collect continuation lines
        cont = []
        # gather lines belonging to this item
        sub = self.collect_item_lines(ind, sp)
        lines = [first] + sub
        if had_blank:
            # blank line inside the item: content is Para(s)
            blocks = self.parse_item_content(lines, ind, sp, True)
            return blocks
        blocks = self.parse_item_content(lines, ind, sp, False)
        return blocks

    def collect_item_lines(self, ind, sp):
        """Collect the continuation lines of a list item."""
        out = []
        base = len(ind) + sp
        while not self.eof():
            l = self.cur()
            if self.blank(l):
                nxt = self.at(1)
                if nxt is not None and (re.match(r'^\s{4,}\S', nxt) or
                                        re.match(r'^%s([-*]|\d+[.)]|[a-zA-Z][.)])[ \t]' %
                                                 re.escape(ind), nxt)):
                    out.append(None)
                    self.pos += 1
                    continue
                break
            if re.match(r'^\s{%d,}' % base, l):
                out.append(self.strip_indent(l, base))
                self.pos += 1
                continue
            break
        return out

    def parse_item_content(self, lines, ind, sp, had_blank):
        text = '\n'.join(x if x is not None else '' for x in lines)
        blocks = self.parse_sub(text)
        if not had_blank and len(blocks) == 1 and blocks[0].t == 'Para':
            return Plain(blocks[0].c[0])
        return blocks

    def parse_ordered_list(self):
        line = self.cur()
        m = re.match(r'^(\s*)(\d+|[ivxlcdmIVXLCDM]+|[a-zA-Z])([.)])(\s+)(.*)$',
                     line)
        if not m:
            return None
        ind, num, delim, sp, rest = m.groups()
        style = self.list_style(num)
        start = self.list_start(num)
        d = el('Period') if delim == '.' else el('OneParen')
        items = []
        pending_blank = False
        while not self.eof():
            l = self.cur()
            if l is None:
                break
            if self.blank(l):
                nxt = self.at(1)
                if nxt is not None and re.match(
                        r'^%s(\d+|[ivxlcdmIVXLCDM]+|[a-zA-Z])[.)]\s+' %
                        re.escape(ind), nxt):
                    pending_blank = True
                    self.pos += 1
                    continue
                break
            m2 = re.match(r'^(%s)(\d+|[ivxlcdmIVXLCDM]+|[a-zA-Z])([.)])(\s+)(.*)$'
                          % re.escape(ind), l)
            if not m2:
                break
            if self.list_style(m2.group(2)) != style or \
                    m2.group(3) != delim:
                break
            if not self.r['fancy_lists'] and not re.match(r'^\d+$', m2.group(2)):
                break
            items.append(self.parse_list_item(ind, len(m2.group(4)),
                                              m2.group(5), pending_blank))
            pending_blank = False
        if not items:
            return None
        return OrderedList([start, style, d], items)

    def list_style(self, num):
        if re.match(r'^\d+$', num):
            return DECIMAL
        if re.match(r'^[ivxlcdm]+$', num):
            return LOWER_ROMAN
        if re.match(r'^[IVXLCDM]+$', num):
            return UPPER_ROMAN
        if re.match(r'^[a-z]+$', num):
            return LOWER_ALPHA
        return UPPER_ALPHA

    def list_start(self, num):
        if re.match(r'^\d+$', num):
            return int(num)
        up = num.upper()
        if re.match(r'^[IVXLCDM]+$', up):
            val = 0
            for ch in up:
                val += ROMAN[ch]
            return val
        # alpha
        val = 0
        for ch in up:
            val = val * 26 + (ord(ch) - ord('A') + 1)
        return val

    # ---------------- line blocks ----------------

    def parse_line_block(self):
        lines = []
        while not self.eof():
            l = self.cur()
            if self.blank(l):
                nxt = self.at(1)
                if nxt is not None and re.match(r'^\s*\|', nxt):
                    lines.append(None)
                    self.pos += 1
                    continue
                break
            if re.match(r'^\s*\|', l):
                m = re.match(r'^\s*\|(.*)$', l)
                lines.append(m.group(1))
                self.pos += 1
                continue
            if lines and re.match(r'^\s', l):
                m = re.match(r'^\s+(.*)$', l)
                lines.append(m.group(1))
                self.pos += 1
                continue
            break
        while lines and lines[-1] is None:
            lines.pop()
        return LineBlock([[self.inl(x)] for x in lines])

    # ---------------- horizontal rule ----------------

    # ---------------- indented code ----------------

    def parse_indented_code(self):
        content = []
        while not self.eof():
            l = self.cur()
            if self.blank(l):
                nxt = self.at(1)
                if nxt is not None and re.match(r'^(\s{4,}|\t)\S', nxt):
                    content.append('')
                    self.pos += 1
                    continue
                break
            if not re.match(r'^(\s{4,}|\t)\S', l):
                break
            content.append(self.strip_indent(l, 4))
            self.pos += 1
        if not content:
            return None
        return CodeBlock(ident(), '\n'.join(content) + '\n')

    # ---------------- html blocks ----------------

    def parse_html_block(self, tag):
        """Parse a block-level HTML tag line."""
        line = self.cur()
        ind = self.indent(line)
        m = re.match(r'^(\s*)<(/?)([a-zA-Z][a-zA-Z0-9]*)([^>]*)>(.*)$', line)
        if not m:
            return None
        closing, tg, attrs, rest = m.group(2), m.group(3).lower(), m.group(4), \
            m.group(5)
        self.pos += 1
        if closing:
            return RawBlock('html', m.group(0))
        # markdown_in_html_blocks: div-like tags become Divs
        if tag in ('div', 'section', 'article', 'aside', 'header', 'footer',
                   'main', 'nav', 'figure', 'figcaption', 'blockquote',
                   'fieldset', 'details', 'summary', 'body', 'html') and \
                self.r['markdown_in_html_blocks']:
            # gather until the matching closing tag
            inner = []
            depth = 1
            close = re.compile(r'^(\s*)</%s\s*>?\s*$' % re.escape(tag))
            while not self.eof():
                l = self.cur()
                if close.match(l):
                    self.pos += 1
                    break
                inner.append(self.strip_indent(l, len(ind)))
                self.pos += 1
            blocks = self.parse_sub('\n'.join(inner))
            attr = self.parse_html_attrs(attrs)
            return Div(attr, blocks)
        # otherwise: raw html block; gather until a blank line
        content = [m.group(0).rstrip()]
        while not self.eof():
            l = self.cur()
            if self.blank(l):
                break
            content.append(l.rstrip())
            self.pos += 1
        return RawBlock('html', '\n'.join(content))

    def parse_comment_block(self):
        line = self.cur()
        if '-->' in line:
            self.pos += 1
            return RawBlock('html', line.strip())
        out = [line.strip()]
        self.pos += 1
        while not self.eof():
            l = self.cur()
            out.append(l.rstrip())
            self.pos += 1
            if '-->' in l:
                break
        return RawBlock('html', '\n'.join(out))

    def parse_html_attrs(self, s):
        s = s.strip()
        ident_name = ''
        classes = []
        keyvals = []
        for m in re.finditer(r'([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*"([^"]*)"|'
                             r"([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*'([^']*)'|"
                             r'([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*([^\s"\']+)|'
                             r'([a-zA-Z_:][-a-zA-Z0-9_:.]*)', s):
            if m.group(1):
                k, v = m.group(1), m.group(2)
            elif m.group(3):
                k, v = m.group(3), m.group(4)
            elif m.group(5):
                k, v = m.group(5), m.group(6)
            else:
                k, v = m.group(7), ''
            if k == 'id':
                ident_name = v
            elif k == 'class':
                classes.extend(v.split())
            else:
                keyvals.append([k, v])
        return [ident_name, classes, keyvals]

    # ---------------- tables ----------------

    def try_pipe_table(self):
        head = self.cur()
        if not re.match(r'^\s*\|', head):
            return None
        sep = self.at(1)
        if sep is None:
            return None
        if not re.match(r'^\s*\|(\s*:?-+:?\s*\|)+\s*$', sep):
            return None
        if self.pos > 0 and self.blank(self.at(-1)) is False and \
                self.at(-1) is not None and not self.blank(self.at(-1)):
            # tables require a preceding blank line
            return None
        headcells = self.pipe_cells(head)
        aligns = self.pipe_aligns(sep)
        if len(headcells) != len(aligns):
            return None
        self.pos += 2
        rows = []
        caption = [None, []]
        while not self.eof():
            l = self.cur()
            if self.blank(l):
                nxt = self.at(1)
                if nxt is not None and re.match(r'^\s*: ', nxt):
                    break
                break
            if not re.match(r'^\s*\|', l):
                break
            rows.append(self.pipe_cells(l))
            self.pos += 1
        # table caption
        if not self.eof():
            l = self.cur()
            m = re.match(r'^\s*:\s+(.*)$', l)
            if m and self.r['table_captions']:
                caption = [None, [Para(self.inl(m.group(1)))]]
                self.pos += 1
        return self.build_table(headcells, rows, aligns, caption)

    def pipe_cells(self, line):
        s = line.strip()
        if s.startswith('|'):
            s = s[1:]
        if s.endswith('|'):
            s = s[:-1]
        parts = re.split(r'(?<!\\)\|', s)
        return [p.strip() for p in parts]

    def pipe_aligns(self, sep):
        s = sep.strip()
        if s.startswith('|'):
            s = s[1:]
        if s.endswith('|'):
            s = s[:-1]
        out = []
        for c in re.split(r'(?<!\\)\|', s):
            c = c.strip()
            if c.startswith(':') and c.endswith(':'):
                a = el('AlignCenter')
            elif c.startswith(':'):
                a = el('AlignLeft')
            elif c.endswith(':'):
                a = el('AlignRight')
            else:
                a = el('AlignDefault')
            out.append(colspec(a, WIDTH_DEFAULT))
        return out

    def build_table(self, headcells, rows, aligns, caption):
        ncols = len(headcells)
        hcells = []
        for i in range(ncols):
            a = aligns[i][0] if i < len(aligns) else el('AlignDefault')
            txt = headcells[i]
            blocks = [Plain(self.inl(txt))] if txt.strip() else []
            hcells.append(cell(ident(), a, 1, 1, blocks))
        head = tablehead(ident(), [row(ident(), hcells)])
        bodies = []
        brows = []
        for r in rows:
            cells = []
            for i in range(ncols):
                a = aligns[i][0] if i < len(aligns) else el('AlignDefault')
                txt = r[i] if i < len(r) else ''
                blocks = [Plain(self.inl(txt))] if txt.strip() else []
                cells.append(cell(ident(), a, 1, 1, blocks))
            brows.append(row(ident(), cells))
        bodies.append(tablebody([], ident(), 0, brows))
        return Table(ident(), caption, aligns, head, bodies,
                     tablebody([], ident(), []))

    def try_grid_table(self):
        head = self.cur()
        if not re.match(r'^\s*\+[-=:+ ]*\+\s*$', head):
            return None
        start = self.pos
        lines = []
        aligns = None
        header = None
        rows = []
        caption = [None, []]
        ind = self.indent(head)
        seppat = re.compile(r'^\s*\+[-=:+ ]*\+\s*$')
        while not self.eof():
            l = self.cur()
            if self.blank(l):
                break
            lines.append(l)
            self.pos += 1
            if seppat.match(l):
                if aligns is None:
                    aligns = self.grid_aligns(l)
                    header = self.grid_rows(lines[:-1], aligns, ind)
                else:
                    rows.append(self.grid_rows(lines[1:-1], aligns, ind))
                lines = [l]
        if aligns is None or header is None:
            self.pos = start
            return None
        if not self.eof():
            l = self.cur()
            m = re.match(r'^\s*:\s+(.*)$', l)
            if m and self.r['table_captions']:
                caption = [None, [Para(self.inl(m.group(1)))]]
                self.pos += 1
        return Table(ident(), caption, aligns, header,
                     [tablebody([], ident(), 0, rows)],
                     tablebody([], ident(), []))

    def grid_aligns(self, sep):
        s = sep.strip().strip('+')
        parts = [p for p in re.split(r'\+', s) if p != '']
        total = sum(len(p) for p in parts) or 1
        out = []
        for p in parts:
            p2 = p.strip()
            if p2.startswith(':') and p2.endswith(':'):
                a = el('AlignCenter')
            elif p2.startswith(':'):
                a = el('AlignLeft')
            elif p2.endswith(':'):
                a = el('AlignRight')
            else:
                a = el('AlignDefault')
            w = float(len(p2)) / float(len(s) + len(parts) - 1) if s else 0
            out.append(colspec(a, el('ColWidth', [w])))
        return out

    def grid_rows(self, lines, aligns, ind):
        if not lines:
            return []
        ncells = len(self.pipe_cells(lines[0]))
        cur = [[] for _ in range(ncells)]
        for l in lines:
            cells = self.pipe_cells(l)
            for i in range(ncells):
                cur[i].append(cells[i] if i < len(cells) else '')
        cells = []
        for i in range(ncells):
            a = aligns[i][0] if i < len(aligns) else el('AlignDefault')
            txt = '\n'.join(cur[i]).strip()
            blocks = [Plain(self.inl(txt))] if txt.strip() else []
            cells.append(cell(ident(), a, 1, 1, blocks))
        return [row(ident(), cells)]

    # ---------------- definition list ----------------

    def parse_definition_list(self, term):
        items = []
        curterm = self.inl(term.strip())
        while True:
            defs = []
            while not self.eof():
                l = self.cur()
                if self.blank(l):
                    nxt = self.at(1)
                    if nxt is not None and re.match(r'^\s*:\s', nxt):
                        break
                    break
                m = re.match(r'^(\s*):\s*(.*)$', l)
                if m:
                    self.pos += 1
                    more = self.collect_item_lines(m.group(1), 1)
                    dlines = [m.group(2)] + [x if x is not None else ''
                                             for x in more]
                    blocks = self.parse_sub('\n'.join(dlines))
                    if len(blocks) == 1 and blocks[0].t == 'Para':
                        blocks = [Plain(blocks[0].c[0])]
                    defs.extend(blocks)
                    continue
                break
            items.append([curterm, defs])
            # next term?
            if self.eof():
                break
            l = self.cur()
            if self.blank(l):
                nxt = self.at(1)
                if nxt is not None and re.match(r'^\s*:\s', nxt):
                    continue
                break
            m = re.match(r'^(\s*)(.*)$', l)
            nxt = self.at(1)
            if nxt is not None and re.match(r'^\s*:\s', nxt):
                curterm = self.inl(m.group(2).strip())
                self.pos += 1
                continue
            break
        return DefinitionList(items)

    # ---------------- footnotes and references ----------------

    def parse_footnote_def(self, key, first):
        self.pos += 1
        lines = [first]
        while not self.eof():
            l = self.cur()
            if self.blank(l):
                nxt = self.at(1)
                if nxt is not None and re.match(r'^\s', nxt):
                    lines.append(None)
                    self.pos += 1
                    continue
                break
            if re.match(r'^\s', l):
                lines.append(self.strip_indent(l, 4))
                self.pos += 1
                continue
            break
        while lines and lines[-1] is None:
            lines.pop()
        blocks = self.parse_sub('\n'.join(x if x is not None else ''
                                          for x in lines))
        self.footnotes[key] = blocks

    def parse_link_def(self, key, rest):
        m = re.match(r'^\s*(\S+)(?:\s+"((?:[^"\\]|\\.)*)")?\s*$', rest)
        m2 = re.match(r'^\s*(\S+)\s+\'([^\']*)\'\s*$', rest)
        m3 = re.match(r'^\s*\((\S+)\s+"([^"]*)"\)\s*$', rest)
        m4 = re.match(r'^\s*(\S+)\s+\(([^)]*)\)\s*$', rest)
        if m3:
            url, title = m3.group(1), m3.group(2)
        elif m2:
            url, title = m2.group(1), m2.group(2)
        elif m4:
            url, title = m4.group(1), m4.group(2)
        elif m:
            url, title = m.group(1), m.group(2) or ''
        else:
            url, title = rest.strip(), ''
        self.refs[key] = [url, title]

    # ---------------- yaml / title ----------------

    def try_yaml_metadata(self):
        line = self.cur()
        if line.strip() != '---':
            return False
        i = self.pos + 1
        while i < len(self.lines) and self.lines[i].strip() != '---':
            i += 1
        if i >= len(self.lines):
            return False
        text = '\n'.join(self.lines[self.pos + 1:i])
        self.pos = i + 1
        self.meta.update(yaml_to_meta(text, self))
        return True

    def parse_title_block(self):
        i = self.pos
        fields = []
        while i < len(self.lines) and self.lines[i].startswith('%'):
            fields.append(self.lines[i][1:].strip())
            i += 1
        self.pos = i
        if not fields:
            return
        title = fields[0]
        self.meta['title'] = El('MetaInlines', self.inl(title))
        if len(fields) > 1 and fields[1]:
            self.meta['author'] = El('MetaList', [
                El('MetaInlines', self.inl(a.strip()))
                for a in fields[1].split(';')])
        if len(fields) > 2 and fields[2]:
            self.meta['date'] = El('MetaInlines', self.inl(fields[2]))

    # ---------------- notes ----------------

    def resolve_notes(self, blocks):
        """Replace NoteRef markers with Note elements."""
        def f(x):
            if isinstance(x, El) and x.t == 'NoteRef':
                blocks = self.footnotes.get(x.c[0])
                if blocks is None:
                    return Str('[^' + x.c[0] + ']')
                return Note(blocks)
            return None
        for i, b in enumerate(blocks):
            blocks[i] = map_blocks_inline(f, b)

    def inl(self, s):
        p = InlineParser(self, s)
        return p.parse()


def map_blocks_inline(f, b):
    if not isinstance(b, El):
        return b
    t = b.t
    if t in ('Plain', 'Para'):
        return el(t, [map_inlines(f, b.c[0])])
    if t == 'LineBlock':
        return el(t, [[map_inlines(f, line) for line in b.c[0]]])
    if t == 'Header':
        return el(t, [b.c[0], b.c[1], map_inlines(f, b.c[2])])
    if t == 'BulletList':
        return el(t, [[map_blocks_inline(f, bl) for bl in item]
                      for item in b.c[0]])
    if t in ('BlockQuote', 'Div'):
        return el(t, [b.c[0], [map_blocks_inline(f, bl) for bl in b.c[1]]])
    if t == 'OrderedList':
        return el(t, [b.c[0], b.c[1],
                      [[map_blocks_inline(f, bl) for bl in item]
                       for item in b.c[2]]])
    if t == 'DefinitionList':
        return el(t, [[[map_inlines(f, item[0]),
                        [map_blocks_inline(f, bl) for bl in item[1]]]
                       for item in b.c[0]]])
    if t == 'Figure':
        return el(t, [b.c[0],
                      [b.c[1][0],
                       [map_blocks_inline(f, bl) for bl in b.c[1][1]]],
                      [map_blocks_inline(f, bl) for bl in b.c[2]]])
    if t == 'Table':
        def mc(c):
            return [c[0], c[1], c[2], c[3],
                    [map_blocks_inline(f, bl) for bl in c[4]]]
        head = [b.c[3][0], [[row(r[0], [mc(c) for c in r[1]])
                             for r in b.c[3][1]]]]
        bodies = [[bd[0], bd[1], bd[2],
                   [[row(r[0], [mc(c) for c in r[1]]) for r in bd[3]]]]
                  for bd in b.c[4]]
        foot = [b.c[5][0], [[row(r[0], [mc(c) for c in r[1]])
                             for r in b.c[5][1]]]]
        cap = [b.c[1][0], [map_blocks_inline(f, bl) for bl in b.c[1][1]]]
        return el(t, [b.c[0], cap, b.c[2], head, bodies, foot])
    return b


def map_inlines(f, xs):
    out = []
    for x in xs:
        if isinstance(x, El) and x.t in ('Emph', 'Underline', 'Strong',
                                         'Strikeout', 'Superscript',
                                         'Subscript', 'SmallCaps',
                                         'Quoted', 'Span'):
            y = f(x)
            if y is not None:
                if isinstance(y, El):
                    y = el(y.t, [c if not isinstance(c, list)
                                 else map_inlines(f, c) for c in y.c])
                out.append(y)
                continue
            out.append(el(x.t, [map_inlines(f, c) if isinstance(c, list)
                                else c for c in x.c]))
            continue
        if isinstance(x, El) and x.t in ('Link', 'Image', 'Note', 'Cite'):
            y = f(x)
            if y is not None:
                out.append(y)
                continue
            newc = []
            for idx, c in enumerate(x.c):
                if idx == 1 and isinstance(c, list):
                    newc.append(map_inlines(f, c))
                else:
                    newc.append(c)
            out.append(el(x.t, newc))
            continue
        y = f(x)
        out.append(y if y is not None else x)
    return out
