    for ch in s:
        if ch == '"':
            out.append('%22')
        elif ch == '&':
            out.append('&amp;')
        elif ch == '<':
            out.append('&lt;')
        elif ch == '>':
            out.append('&gt;')
        else:
            out.append(ch)
    return ''.join(out)


