            return [Atom(x.c[1], True)]
        if t == 'Link':
            a = x.c[0]
            attrs = ''
            href = ' href="%s"' % esc_url(x.c[2][0])
            if x.c[2][1]:
                href += ' title="%s"' % esc(x.c[2][1])
            if a[0]:
                href += ' id="%s"' % esc(a[0])
            if a[1]:
                href += ' class="%s"' % esc(' '.join(a[1]))
            for k, v in a[2]:
                href += ' %s="%s"' % (esc(k), esc(v))
            out = [Atom('<a%s>' % href, True)]
            out.extend(self.inline_atoms(x.c[1]))
            out.append(Atom('</a>'))
