            if alt:
                attrs += ' alt="%s"' % esc(alt)
            if a[0]:
                attrs += ' id="%s"' % esc(a[0])
            if a[1]:
                attrs += ' class="%s"' % esc(' '.join(a[1]))
            for k, v in a[2]:
                attrs += ' %s="%s"' % (esc(k), esc(v))
