                        'role="doc-noteref">' % (n, n), True),
                   Atom('<sup>%d</sup>' % n), Atom('</a>')]
            return out
        if t == 'Span':
            a = x.c[0]
            attrs = ''
            if a[0]:
                attrs += ' id="%s"' % esc(a[0])
            if a[1]:
                attrs += ' class="%s"' % esc(' '.join(a[1]))
            for k, v in a[2]:
                attrs += ' %s="%s"' % (esc(k), esc(v))
            out = [Atom('<span%s>' % attrs, True)]
            out.extend(self.inline_atoms(x.c[1]))
            out.append(Atom('</span>'))
