def esc(s):
    """Escape HTML text."""
    out = []
    for ch in s:
        if ch == '<':
            out.append('&lt;')
        elif ch == '>':
            out.append('&gt;')
        elif ch == '&':
            out.append('&amp;')
        elif ch == '"':
            out.append('&quot;')
        else:
            out.append(ch)
    return ''.join(out)


def esc_url(s):
    out = []
    for ch in s:
