    def block_lines(self, b, indent=0):
        pad = ' ' * indent
        t = b.t
        if t == 'Plain':
            return self.fill(self.inline_atoms(b.c[0]), self.width, indent)
        if t == 'Para':
            return self.fill(self.inline_atoms(b.c[0]), self.width, indent)
        if t == 'Header':
            level = b.c[0]
            text = self.inline_atoms(b.c[2])
            ident = self.header_id(b)
            if text and text[0].s.startswith(' ') and False:
                pass
            if self.o.get('number-sections'):
                num = self.section_number()
                if num:
                    text = [Atom('<span class="header-section-number">%s</span>'
                                 % num, False)] + text
            open_ = '<h%d id="%s">' % (level, ident)
            out = self.fill([Atom(open_)] + text + [Atom('</h%d>' % level)],
                            self.width, indent)
            return out
        if t == 'HorizontalRule':
            return [pad + '<hr />']
        if t == 'CodeBlock':
            return self.code_block_lines(b, indent)
        if t == 'RawBlock':
            return [pad + l for l in b.c[1].split('\n')]
        if t == 'BlockQuote':
            inner = []
            for bl in b.c[1]:
                inner.extend(self.block_lines(bl))
            return [pad + '<blockquote>'] + inner + [pad + '</blockquote>']
        if t == 'BulletList':
            out = [pad + '<ul>']
            for item in b.c[0]:
                out.extend(self.list_item(item, '<li>', '</li>', indent))
            out.append(pad + '</ul>')
            return out
        if t == 'OrderedList':
            out = [pad + self.open_ordered(b)]
            for item in b.c[2]:
                out.extend(self.list_item(item, '<li>', '</li>', indent))
            out.append(pad + '</ol>')
            return out
        if t == 'DefinitionList':
            out = [pad + '<dl>']
            for item in b.c[0]:
                term = self.fill(self.inline_atoms(item[0]), self.width,
                                 indent + 0)
                out.append(pad + '<dt>' + ''.join(a.s for a in
                                                  self.inline_atoms(item[0]))
                           + '</dt>')
                for d in item[1]:
                    if d.t == 'Plain':
                        out.append(pad + '<dd>')
                        out.append(pad + inline_text([d]))
                        out.append(pad + '</dd>')
                    else:
                        out.append(pad + '<dd>')
                        for bl in [d]:
                            out.extend(self.block_lines(bl, indent))
                        out.append(pad + '</dd>')
            out.append(pad + '</dl>')
            return out
        if t == 'Div':
            attrs = self.attr_string(b.c[0])
            open_ = '<div%s>' % attrs
            inner = []
            for bl in b.c[1]:
                inner.extend(self.block_lines(bl, indent))
            return [pad + open_] + inner + [pad + '</div>']
        if t == 'Figure':
            return self.figure_lines(b, indent)
        if t == 'Table':
            return self.table_lines(b, indent)
        if t == 'LineBlock':
            inner = []
            for i, line in enumerate(b.c[0]):
                if i:
                    inner.append(Atom('<br />'))
                    inner.append(Atom('\n'))
                inner.extend(self.inline_atoms(line))
            return [pad + '<div class="line-block">' + ''.join(
                a.s for a in inner) + '</div>']
        return [pad + esc(inline_text([b]))]

    def list_item(self, item, pre, post, indent):
        pad = ' ' * indent
        out = [pad + pre]
        first = True
        for bl in item:
            ls = self.block_lines(bl, indent + 0)
            if first:
                if bl.t in ('Para', 'Plain'):
                    # content on the same line as <li>
                    body = self.fill(self.inline_atoms(bl.c[0]), self.width,
                                     indent)
                    out[-1] = pad + pre + body[0][indent:]
                    out.extend(body[1:])
                else:
                    out.extend(ls)
                first = False
            else:
                out.extend(ls)
        out[-1] = out[-1] + post if out else pad + post
        if not item:
            out.append(pad + post)
        return out

    def open_ordered(self, b):
        style = b.c[0][1].t
        start = b.c[0][0]
        delim = b.c[0][2].t
        typ = {None: None}
        m = {'Decimal': '1', 'LowerAlpha': 'a', 'UpperAlpha': 'A',
             'LowerRoman': 'i', 'UpperRoman': 'I'}[style]
        s = '<ol'
        if delim == 'OneParen':
            pass
        if start != 1:
            s += ' start="%d"' % start
        s += ' type="%s"' % m
        return s + '>'

    def header_id(self, b):
        key = ('h', b.c[1][0]) if b.c[1][0] else None
        if b.c[1][0]:
            return b.c[1][0]
        txt = inline_text(b.c[2])
        base = slugify(txt)
        n = self.header_ids.get(base, 0)
        self.header_ids[base] = n + 1
        return base if n == 0 else '%s-%d' % (base, n)

    def code_block_lines(self, b, indent):
        a = b.c[0]
        txt = b.c[1].rstrip('\n')
        pad = ' ' * indent
        if not a[1]:
            return [pad + '<pre><code>' + esc(txt) + '</code></pre>']
        lang = a[1][0] if a[1] else ''
        ident = a[0] or self.next_code_id()
        cls = ' '.join(a[1])
        inner = self.highlight(txt, lang, ident)
        return [pad + '<div class="sourceCode" id="%s"><pre' % ident,
                pad + 'class="sourceCode %s"><code class="sourceCode %s">%s'
                '</code></pre></div>' % (cls, lang, inner)]

    def next_code_id(self):
        self._cbn = getattr(self, '_cbn', 0) + 1
        return 'cb%d' % self._cbn

    def highlight(self, txt, lang, ident):
        out = []
        for i, line in enumerate(txt.split('\n')):
            out.append('<span id="%s-%d"><a href="#%s-%d" aria-hidden="true" '
                       'tabindex="-1"></a>%s</span>'
                       % (ident, i + 1, ident, i + 1, esc(line)))
        return '\n'.join(out)

    def figure_lines(self, b, indent):
        pad = ' ' * indent
        cap = b.c[1]
        body = []
        for bl in b.c[2]:
            body.extend(self.block_lines(bl, indent))
        caption_text = None
        if cap[0]:
            caption_text = self.inline_atoms(cap[0])
        elif len(cap[1]) == 1 and cap[1][0].t == 'Plain':
            caption_text = self.inline_atoms(cap[1][0].c[0])
        out = [pad + '<figure>']
        out.extend(body)
        if caption_text is not None:
            out.append(pad + '<figcaption aria-hidden="true">' +
                       ''.join(a.s for a in caption_text) +
                       '</figcaption>')
        out.append(pad + '</figure>')
        return out

    def table_lines(self, b, indent):
        pad = ' ' * indent
        out = [pad + '<table>']
        cap = b.c[1]
        if cap[1]:
            caplines = []
            for bl in cap[1]:
                caplines.extend(self.block_lines(bl))
            if len(caplines) == 1:
                out.append(pad + '<caption>' + caplines[0].strip() +
                           '</caption>')
            else:
                out.append(pad + '<caption>')
                out.extend(caplines)
                out.append(pad + '</caption>')
        head = b.c[3]
        if head[1]:
            out.append(pad + '<thead>')
            for r in head[1]:
                out.extend(self.row_lines(r, 'th', indent))
            out.append(pad + '</thead>')
        for bd in b.c[4]:
            out.append(pad + '<tbody>')
            for r in bd[3]:
                out.extend(self.row_lines(r, 'td', indent))
            out.append(pad + '</tbody>')
        foot = b.c[5]
        if foot[1]:
            out.append(pad + '<tfoot>')
            for r in foot[1]:
                out.extend(self.row_lines(r, 'td', indent))
            out.append(pad + '</tfoot>')
        out.append(pad + '</table>')
        return out

    def row_lines(self, r, tag, indent):
        pad = ' ' * indent
        out = [pad + '<tr>']
        for c in r[1]:
            attrs = ''
            style = self.align_style(c[1])
            if style:
                attrs += ' style="%s"' % style
            if c[2] != 1:
                attrs += ' rowspan="%d"' % c[2]
            if c[3] != 1:
                attrs += ' colspan="%d"' % c[3]
            inner = []
            for bl in c[4]:
                inner.extend(self.block_lines(bl))
            if len(inner) == 1:
                out.append(pad + '<%s%s>%s</%s>' % (tag, attrs,
                                                    inner[0].strip(), tag))
            else:
                out.append(pad + '<%s%s>' % (tag, attrs))
                out.extend(inner)
                out.append(pad + '</%s>' % tag)
        out.append(pad + '</tr>')
        return out

    def align_style(self, a):
        if a.t == 'AlignLeft':
            return 'text-align: left;'
        if a.t == 'AlignRight':
            return 'text-align: right;'
        if a.t == 'AlignCenter':
            return 'text-align: center;'
        return None

    def section_number(self):
        self._num = getattr(self, '_num', 0) + 1
        return str(self._num)

    def attr_string(self, a):
        s = ''
        if a[0]:
            s += ' id="%s"' % esc(a[0])
        if a[1]:
            s += ' class="%s"' % esc(' '.join(a[1]))
        for k, v in a[2]:
            s += ' %s="%s"' % (esc(k), esc(v))
        return s

    def next_note_num(self):
        return len(self.notes) + 1


def inline_text(xs):
    out = []
    for x in xs:
        if isinstance(x, El):
            t = x.t
            if t == 'Str':
                out.append(x.c[0])
            elif t == 'Space':
                out.append(' ')
            elif t == 'SoftBreak':
                out.append(' ')
            elif t == 'LineBreak':
                out.append('\n')
            elif t in ('Code', 'Math'):
                out.append(x.c[1])
            elif t == 'RawInline':
                out.append(x.c[1])
            elif t == 'Link':
                out.append(inline_text(x.c[1]))
            elif t == 'Image':
                out.append(inline_text(x.c[1]))
            elif t in ('Emph', 'Underline', 'Strong', 'Strikeout',
                       'Superscript', 'Subscript', 'SmallCaps', 'Span',
                       'Quoted'):
                out.append(inline_text(x.c[1]))
            elif t == 'Note':
                out.append('')
            elif t == 'Cite':
                out.append(inline_text(x.c[1]))
        else:
            out.append(str(x))
    return ''.join(out)
