def help_text(prog):
    d = datamod.read_data('help.txt')
    t = d.decode('utf-8')
    return t.replace('PANDOCPROG', prog)


# ---------------- conversion ----------------

READER_FORMATS = None
WRITER_FORMATS = None


def input_format_names():
    return set(datamod.input_formats())


def output_format_names():
    return set(datamod.output_formats())


def convert(opts, prog):
    infmt = opts.get('from')
    outfmt = opts.get('to')

    files = opts.files

    if not files:
        data = sys.stdin.buffer.read()
        inputs = [data.decode('utf-8', 'replace')]
        if infmt is None:
            infmt = 'markdown'
    else:
        inputs = []
        for f in files:
            try:
                with open(f, 'rb') as fh:
                    inputs.append(fh.read())
            except OSError as e:
                err('%s: %s: withBinaryFile: does not exist (No such file '
                    'or directory)' % (prog, f), 1)
        inputs = [x.decode('utf-8', 'replace') for x in inputs]
        if infmt is None:
            exts = [os.path.splitext(f)[1] for f in files]
            unknown = [e for e in exts if e[1:].lower() not in
                       datamod.EXT_TO_FORMAT]
            if unknown:
                msg = ('Could not deduce format from file extension '
                       + ' or '.join(e for e in unknown))
                warn('[WARNING] ' + msg + '\n  Defaulting to markdown')
            infmt = None
            for e in exts:
                if e[1:].lower() in datamod.EXT_TO_FORMAT:
                    infmt = datamod.EXT_TO_FORMAT[e[1:].lower()]
                    break
            if infmt is None:
                infmt = 'markdown'

    if outfmt is None:
        if opts.has('output'):
            e = os.path.splitext(opts.get('output'))[1]
            if e[1:].lower() in datamod.EXT_TO_FORMAT:
                f = datamod.EXT_TO_FORMAT[e[1:].lower()]
                outfmt = f if f in output_format_names() else None
        if outfmt is None:
            outfmt = 'html'
    if outfmt not in ('html', 'html5', 'html4') and \
            outfmt not in output_format_names():
        err('Unknown output format %s' % outfmt, 22)
    if infmt not in input_format_names():
        err('Unknown input format %s' % infmt, 21)

    # read the input
    text = '\n\n'.join(inputs)
    doc = read_document(text, infmt, opts)

    out = write_document(doc, outfmt, opts)

    if opts.has('output'):
        path = opts.get('output')
        d = os.path.dirname(path)
        if d:
            try:
                os.makedirs(d, exist_ok=True)
            except OSError as e:
                err('%s: %s: createDirectory: permission denied (Permission '
                    'denied)' % (prog, os.path.dirname(path)), 1)
        try:
            with open(path, 'w', encoding='utf-8') as fh:
                fh.write(out)
        except OSError as e:
            err('%s: %s: openFile: does not exist (No such file or '
                'directory)' % (prog, path), 1)
    else:
        try:
            sys.stdout.write(out)
        except BrokenPipeError:
            pass
    return 0


def read_document(text, fmt, opts):
    spec = opts.get('from')
    base, exts = parse_ext_spec(spec) if spec else (fmt, [])
    reader = Reader(base if base in ('markdown', 'commonmark', 'commonmark_x',
                                     'gfm', 'markdown_github') else fmt,
                    exts)
    p = MdParser(reader, opts)
    return p.parse(text)


def write_document(doc, fmt, opts):
    if fmt in ('json',):
        return jsonenc.dumps(doc) + '\n'
    if fmt in ('native',):
        return native.write_native(doc, opts.has('standalone')) + '\n'
    if fmt in ('html', 'html5', 'html4'):
        from .html import HtmlWriter
        from .templating import parse as tparse, render as trender
        w = HtmlWriter(opts)
        body = w.render_body(doc)
        if opts.has('standalone'):
            tmpl = datamod.default_template('html4' if fmt == 'html4'
                                            else 'html')
            ctx = w.template_context(doc, opts)
            return trender(tparse(tmpl), ctx)
        return body
    if fmt in ('plain',):
        from .plain import PlainWriter
        return PlainWriter(opts).write(doc)
    if fmt in ('markdown', 'commonmark', 'commonmark_x', 'gfm',
               'markdown_github', 'markdown_strict', 'markdown_mmd',
               'markdown_phpextra', 'markua'):
        from .writers_md import write_markdown
        return write_markdown(doc, fmt, opts)
    if fmt in ('latex', 'beamer'):
        from .writers_tex import write_latex
        return write_latex(doc, fmt, opts)
    if fmt in ('rst',):
        from .writers_rst import write_rst
        return write_rst(doc, opts)
    if fmt in ('man',):
        from .writers_man import write_man
        return write_man(doc, opts)
    err('Unsupported output format %s' % fmt, 22)
