                s += ' class="%s"' % esc(' '.join(a[1]))
            for k, v in a[2]:
                s += ' %s="%s"' % (esc(k), esc(v))
            s += '>'
            out = self.tag(s)
            out.extend(self.inline_atoms(x.c[1]))
            out.append(Atom('</span>'))
            return out
        if t == 'Cite':
            return self.atoms(inline_text([x]), True)
        return [Atom(esc(inline_text([x])), True)]

    def wrap_inline(self, pre, post, xs):
        out = self.tag(pre)
        out.extend(self.inline_atoms(xs))
        out.append(Atom(post))
        return out

    def link_atoms(self, x):
        a = x.c[0]
        s = '<a href="%s"' % esc_url(x.c[2][0])
        if x.c[2][1]:
            s += ' title="%s"' % esc(x.c[2][1])
        if a[0]:
            s += ' id="%s"' % esc(a[0])
        if a[1]:
            s += ' class="%s"' % esc(' '.join(a[1]))
        for k, v in a[2]:
            s += ' %s="%s"' % (esc(k), esc(v))
        s += '>'
        out = self.tag(s, brk_last=True)
        out.extend(self.inline_atoms(x.c[1]))
        out.append(Atom('</a>'))
        return out

    def image_atoms(self, x):
        a = x.c[0]
        alt = inline_text(x.c[1])
        title = x.c[2][1]
        s = '<img src="%s"' % esc_url(x.c[2][0])
        if title:
            s += ' title="%s"' % esc(title)
        if alt:
            s += ' alt="%s"' % esc(alt)
        if a[0]:
            s += ' id="%s"' % esc(a[0])
        if a[1]:
            s += ' class="%s"' % esc(' '.join(a[1]))
        for k, v in a[2]:
            s += ' %s="%s"' % (esc(k), esc(v))
        s += ' />'
        return self.tag(s, brk_last=True)

    def note_atoms(self, x):
        n = len(self.notes) + 1
        self.notes.append((n, x.c[0]))
        s = ('<a href="#fn%d" class="footnote-ref" id="fnref%d" '
             'role="doc-noteref"><sup>%d</sup>' % (n, n, n))
        return self.tag(s) + [Atom('</a>')]

    def math_atoms(self, x):
        from .mathml import math_atoms
        return math_atoms(self, x)

    # ---------------- blocks ----------------

    def block_lines(self, b, indent=0):
        pad = ' ' * indent
        t = b.t
        if t in ('Plain', 'Para'):
            return self.fill(self.inline_atoms(b.c[0]), self.width, indent)
        if t == 'Header':
            return self.header_lines(b, indent)
        if t == 'HorizontalRule':
            return [pad + '<hr />']
        if t == 'CodeBlock':
            return self.code_block_lines(b, indent)
        if t == 'RawBlock':
            return [pad + l for l in b.c[1].split('\n')]
        if t == 'BlockQuote':
            inner = []
            for bl in b.c[1]:
                inner.extend(self.block_lines(bl))
            return [pad + '<blockquote>'] + inner + [pad + '</blockquote>']
        if t == 'BulletList':
            out = [pad + '<ul>']
            for item in b.c[0]:
                out.extend(self.list_item(item, '<li>', '</li>', indent))
            out.append(pad + '</ul>')
            return out
        if t == 'OrderedList':
            out = [pad + self.open_ordered(b)]
            for item in b.c[2]:
                out.extend(self.list_item(item, '<li>', '</li>', indent))
            out.append(pad + '</ol>')
            return out
        if t == 'DefinitionList':
            return self.deflist_lines(b, indent)
        if t == 'Div':
            attrs = self.attr_string(b.c[0])
            open_ = '<div%s>' % attrs
            inner = []
            for bl in b.c[1]:
                inner.extend(self.block_lines(bl, indent))
            return [pad + open_] + inner + [pad + '</div>']
        if t == 'Figure':
            return self.figure_lines(b, indent)
        if t == 'Table':
            return self.table_lines(b, indent)
        if t == 'LineBlock':
            inner = []
            for i, line in enumerate(b.c[0]):
                if i:
                    inner.append(Atom('<br />', False))
                    inner.append(Atom('\n', False))
                inner.extend(self.inline_atoms(line))
            return [pad + '<div class="line-block">' + ''.join(
                a.s for a in inner) + '</div>']
        return [pad + esc(inline_text([b]))]

    def list_item(self, item, pre, post, indent):
        pad = ' ' * indent
        out = []
        body = []
        first = True
        for bl in item:
            if bl.t in ('Para', 'Plain'):
                ls = self.fill(self.inline_atoms(bl.c[0]), self.width, indent)
            else:
                ls = self.block_lines(bl, indent)
            if first:
                out.append(pad + pre + (ls[0][indent:] if ls else ''))
                out.extend(ls[1:])
                first = False
            else:
                out.extend(ls)
        if out:
            out[-1] = out[-1] + post
        else:
            out.append(pad + pre + post)
        return out

    def deflist_lines(self, b, indent):
        pad = ' ' * indent
        out = [pad + '<dl>']
        for item in b.c[0]:
            term = self.fill(self.inline_atoms(item[0]), self.width, indent)
            out.append(pad + '<dt>' + term[0][indent:] + '</dt>')
            if len(term) > 1:
                out.extend(term[1:])
            for d in item[1]:
                if d.t == 'Plain':
                    out.append(pad + '<dd>')
                    out.extend(self.block_lines(d, indent))
                    out.append(pad + '</dd>')
                else:
                    out.append(pad + '<dd>')
                    out.extend(self.block_lines(d, indent))
                    out.append(pad + '</dd>')
        out.append(pad + '</dl>')
        return out

    def open_ordered(self, b):
        style = b.c[0][1].t
        start = b.c[0][0]
        m = {'Decimal': '1', 'LowerAlpha': 'a', 'UpperAlpha': 'A',
             'LowerRoman': 'i', 'UpperRoman': 'I'}[style]
        s = '<ol'
        if start != 1:
            s += ' start="%d"' % start
        s += ' type="%s">' % m
        return s

    def header_lines(self, b, indent):
        level = b.c[0]
        text = self.inline_atoms(b.c[2])
        ident = self.header_id(b)
        if self.o.get('number-sections'):
            num = self.section_number()
            if num:
                text = self.tag('<span class="header-section-number">%s</span>'
                                % num) + [Atom(' ', True)] + text
        open_ = '<h%d id="%s">' % (level, ident)
        out = self.fill(self.tag(open_) + text +
                        self.tag('</h%d>' % level, brk_last=False),
                        self.width, indent)
        return out

    def header_id(self, b):
        if b.c[1][0]:
            return b.c[1][0]
        txt = inline_text(b.c[2])
        base = slugify(txt)
        n = self.header_ids.get(base, 0)
        self.header_ids[base] = n + 1
        return base if n == 0 else '%s-%d' % (base, n)

    def code_block_lines(self, b, indent):
        a = b.c[0]
        txt = b.c[1].rstrip('\n')
        pad = ' ' * indent
        if not a[1]:
            return [pad + '<pre><code>' + esc(txt) + '</code></pre>']
        lang = a[1][0] if a[1] else ''
        ident = a[0] or self.next_code_id()
        cls = ' '.join(a[1])
        inner = self.highlight(txt, lang, ident)
        return [pad + '<div class="sourceCode" id="%s"><pre' % ident,
                pad + 'class="sourceCode %s"><code class="sourceCode %s">%s'
                '</code></pre></div>' % (cls, lang, inner)]

    def next_code_id(self):
        self._cbn += 1
        return 'cb%d' % self._cbn

    def highlight(self, txt, lang, ident):
        from .highlight import highlight_code
        return highlight_code(txt, lang, ident)

    def figure_lines(self, b, indent):
        pad = ' ' * indent
        cap = b.c[1]
        body = []
        for bl in b.c[2]:
            body.extend(self.block_lines(bl, indent))
        caption_text = None
        if cap[0]:
            caption_text = self.inline_atoms(cap[0])
        elif len(cap[1]) == 1 and cap[1][0].t == 'Plain':
            caption_text = self.inline_atoms(cap[1][0].c[0])
        out = [pad + '<figure>']
        out.extend(body)
        if caption_text is not None:
            out.append(pad + '<figcaption aria-hidden="true">' +
                       ''.join(a.s for a in caption_text) +
                       '</figcaption>')
        out.append(pad + '</figure>')
        return out

    def table_lines(self, b, indent):
        pad = ' ' * indent
        out = [pad + '<table>']
        cap = b.c[1]
        if cap[1]:
            caplines = []
            for bl in cap[1]:
                caplines.extend(self.block_lines(bl))
            if len(caplines) == 1:
                out.append(pad + '<caption>' + caplines[0][len(pad):] +
                           '</caption>')
            else:
                out.append(pad + '<caption>')
                out.extend(caplines)
                out.append(pad + '</caption>')
        head = b.c[3]
        if head[1]:
            out.append(pad + '<thead>')
            for r in head[1]:
                out.extend(self.row_lines(r, 'th', indent))
            out.append(pad + '</thead>')
        for bd in b.c[4]:
            out.append(pad + '<tbody>')
            for r in bd[3]:
                out.extend(self.row_lines(r, 'td', indent))
            out.append(pad + '</tbody>')
        foot = b.c[5]
        if foot[1]:
            out.append(pad + '<tfoot>')
            for r in foot[1]:
                out.extend(self.row_lines(r, 'td', indent))
            out.append(pad + '</tfoot>')
        out.append(pad + '</table>')
        return out

    def row_lines(self, r, tag, indent):
        pad = ' ' * indent
        out = [pad + '<tr>']
        for c in r[1]:
            attrs = ''
            style = self.align_style(c[1])
            if style:
                attrs += ' style="%s"' % style
            if c[2] != 1:
                attrs += ' rowspan="%d"' % c[2]
            if c[3] != 1:
                attrs += ' colspan="%d"' % c[3]
            inner = []
            for bl in c[4]:
                inner.extend(self.block_lines(bl))
            if len(inner) == 1:
                out.append(pad + '<%s%s>%s</%s>' % (tag, attrs,
                                                    inner[0][len(pad):],
                                                    tag))
            else:
                out.append(pad + '<%s%s>' % (tag, attrs))
                out.extend(inner)
                out.append(pad + '</%s>' % tag)
        out.append(pad + '</tr>')
        return out

    def align_style(self, a):
        if a.t == 'AlignLeft':
            return 'text-align: left;'
        if a.t == 'AlignRight':
            return 'text-align: right;'
        if a.t == 'AlignCenter':
            return 'text-align: center;'
        return None

    def attr_string(self, a):
        s = ''
        if a[0]:
            s += ' id="%s"' % esc(a[0])
        if a[1]:
            s += ' class="%s"' % esc(' '.join(a[1]))
        for k, v in a[2]:
            s += ' %s="%s"' % (esc(k), esc(v))
        return s

    # ---------------- document ----------------

    def render_body(self, doc):
        lines = []
        for b in doc.blocks:
            lines.extend(self.block_lines(b))
        if self.notes:
            lines.append('<section id="footnotes" class="footnotes '
                         'footnotes-end-of-document" role="doc-endnotes">')
            lines.append('<hr />')
            lines.append('<ol>')
            for n, blocks in self.notes:
                inner = []
                for bl in blocks:
                    inner.extend(self.block_lines(bl))
                if len(inner) == 1:
                    lines.append('<li id="fn%d">%s<a href="#fnref%d" '
                                 'class="footnote-back" role="doc-backlink">'
                                 '\u21a9\ufe0e</a></li>' % (n, inner[0], n))
                else:
                    lines.append('<li id="fn%d">' % n)
                    lines.extend(inner)
                    lines.append('<a href="#fnref%d" class="footnote-back" '
                                 'role="doc-backlink">\u21a9\ufe0e</a></li>'
                                 % n)
            lines.append('</ol>')
            lines.append('</section>')
        return '\n'.join(lines) + '\n'

    def section_number(self):
        self._num = getattr(self, '_num', 0) + 1
        return str(self._num)

    def template_context(self, doc, opts):
        from .ast import Str
        meta = doc.meta

        def get_meta_inlines(key):
            v = meta.get(key)
            if v is None:
                return ''
            if isinstance(v, El) and v.t == 'MetaInlines':
                return inline_text(v.c[0])
            if isinstance(v, El) and v.t == 'MetaString':
                return v.c[0]
            if isinstance(v, El) and v.t == 'MetaList':
                return '\n'.join(inline_text(x.c[0]) for x in v.c[0]
                                 if isinstance(x, El))
            return inline_text([v]) if isinstance(v, El) else str(v)

        def get_meta_list(key):
            v = meta.get(key)
            if v is None:
                return []
            if isinstance(v, El) and v.t == 'MetaList':
                return [inline_text(x.c[0]) if isinstance(x, El) and
                        x.t == 'MetaInlines' else
                        (x.c[0] if isinstance(x, El) and x.t == 'MetaString'
                         else '') for x in v.c[0]]
            if isinstance(v, El) and v.t in ('MetaInlines', 'MetaString'):
                return [get_meta_inlines(key)]
            return []

        title = get_meta_inlines('title')
        subtitle = get_meta_inlines('subtitle')
        authors = get_meta_list('author')
        date = get_meta_inlines('date')
        abstract = ''
        av = meta.get('abstract')
        if isinstance(av, El) and av.t == 'MetaInlines':
            abstract = inline_text(av.c[0])
        title_prefix = opts.get('title-prefix', '')
        pagetitle = title if title else '-'
        ctx = {}
        ctx['title'] = title
        ctx['pagetitle'] = (title_prefix + ' \u2013 ' + pagetitle
                            if title_prefix else pagetitle)
        ctx['subtitle'] = subtitle
        ctx['author'] = authors
        ctx['author-meta'] = authors
        ctx['date'] = date
        ctx['date-meta'] = date
        ctx['abstract'] = abstract
        ctx['abstract-title'] = get_meta_inlines('abstract-title') or 'Abstract'
        ctx['keywords'] = get_meta_list('keywords')
        ctx['description-meta'] = get_meta_inlines('description')
        ctx['lang'] = opts.get('lang', '')
        ctx['dir'] = opts.get('dir', '')
        ctx['css'] = opts.get('css') or []
        ctx['idprefix'] = opts.get('id-prefix', '')
        ctx['title-prefix'] = title_prefix
        ctx['toc'] = bool(opts.get('toc') or opts.get('table-of-contents'))
        ctx['toc-title'] = get_meta_inlines('toc-title')
        ctx['math'] = ''
        ctx['header-includes'] = []
        ctx['include-before'] = []
        ctx['include-after'] = []
        ctx['styles.html'] = None
        body = self.render_body(doc)
        if ctx['toc']:
            ctx['table-of-contents'] = self.render_toc(doc)
        else:
            ctx['table-of-contents'] = ''
        ctx['body'] = body
        ctx['include-before'] = self.includes(opts, 'include-before-body')
        ctx['include-after'] = self.includes(opts, 'include-after-body')
        ctx['header-includes'] = self.includes(opts, 'include-in-header')
        return ctx

    def includes(self, opts, key):
        out = []
        if opts.has(key):
            for f in (opts.get(key) if isinstance(opts.get(key), list)
                      else [opts.get(key)]):
                try:
                    with open(f, encoding='utf-8') as fh:
                        out.append(fh.read())
                except OSError:
                    pass
        return out

    def render_toc(self, doc):
        out = ['<ul>']
        self._toc(doc.blocks, out, [])
        out.append('</ul>')
        return '\n'.join(out)

    def _toc(self, blocks, out, nums):
        n = 0
        started = False
        for b in blocks:
            if b.t == 'Header':
                level = b.c[0]
                n += 1
                nums2 = nums + [n]
                numstr = '.'.join(str(x) for x in nums2)
                ident = self.header_id(b)
                txt = inline_text(b.c[2])
                out.append('<li><a href="#%s" id="toc-%s">'
                           '<span class="toc-section-number">%s</span> %s</a>'
                           % (ident, ident, numstr, esc(txt)))
                sub = []
                self._toc_sub(blocks, i=None, out=sub, nums=nums2)
                out.extend(sub)
                out.append('</li>')
        return out


def inline_text(xs):
    out = []
    for x in xs:
        if isinstance(x, El):
            t = x.t
            if t == 'Str':
                out.append(x.c[0])
            elif t == 'Space':
                out.append(' ')
            elif t == 'SoftBreak':
                out.append(' ')
            elif t == 'LineBreak':
                out.append('\n')
            elif t in ('Code', 'Math'):
                out.append(x.c[1])
            elif t == 'RawInline':
                out.append(x.c[1])
            elif t == 'Link':
                out.append(inline_text(x.c[1]))
            elif t == 'Image':
                out.append(inline_text(x.c[1]))
            elif t in ('Emph', 'Underline', 'Strong', 'Strikeout',
                       'Superscript', 'Subscript', 'SmallCaps', 'Span',
                       'Quoted'):
                out.append(inline_text(x.c[1]))
            elif t == 'Note':
                out.append('')
            elif t == 'Cite':
                out.append(inline_text(x.c[1]))
        else:
            out.append(str(x))
    return ''.join(out)
