"""HTML writer."""
import re

from .ast import (El, Doc, Str, Para, Plain, Header, CodeBlock, BlockQuote,
                  BulletList, OrderedList, DefinitionList, HorizontalRule,
                  Div, Figure, LineBlock, RawBlock, Table, Note, Span)


class Atom:
    """A piece of html output; brk says whether a soft break may be
    inserted before it."""
    __slots__ = ('s', 'brk')

    def __init__(self, s, brk=False):
        self.s = s
        self.brk = brk


def esc(s):
    out = []
    for ch in s:
        if ch == '<':
            out.append('&lt;')
        elif ch == '>':
            out.append('&gt;')
        elif ch == '&':
            out.append('&amp;')
        elif ch == '"':
            out.append('&quot;')
        else:
            out.append(ch)
    return ''.join(out)


def esc_url(s):
    out = []
    for ch in s:
        if ch == '"':
            out.append('%22')
        elif ch == '&':
            out.append('&amp;')
        elif ch == '<':
            out.append('&lt;')
        elif ch == '>':
            out.append('&gt;')
        else:
            out.append(ch)
    return ''.join(out)


def slugify(s):
    parts = re.split(r'[ \t\n]+', s.lower())
    keep = []
    for p in parts:
        p2 = ''.join(c for c in p if c.isalnum() or c in '._-')
        if p2:
            keep.append(p2)
    if not keep:
        return 'section'
    return '-'.join(keep)


def split_tag(s):
    """Split an html tag string at spaces not inside quotes; returns a list
    of pieces (the first without a leading space, the rest with)."""
    out = []
    cur = ''
    q = None
    for ch in s:
        if q:
            cur += ch
            if ch == q:
                q = None
            continue
        if ch in '"\'':
            q = ch
            cur += ch
            continue
        if ch == ' ':
            if cur:
                out.append(cur)
                cur = ''
            continue
        cur += ch
    if cur:
        out.append(cur)
    return out


class HtmlWriter:
    def __init__(self, opts):
        self.o = opts
        self.ids = {}
        self.notes = []
        self.header_ids = {}
        self.width = opts.get('columns', 72)
        self.wrap = opts.get('wrap', 'auto')
        self._cbn = 0

    # ---------------- atoms ----------------

    def atoms(self, s, brk=False):
        """Split text into atoms at spaces (nbsp not breakable)."""
        out = []
        if not s:
            return out
        parts = re.split(r'( +)', s)
        first = True
        for p in parts:
            if p == '':
                continue
            if set(p) <= {' ', '\t'}:
                out.append(Atom(p.replace('\t', ' '), True))
                continue
            out.append(Atom(esc(p), brk or not first))
            first = False
        return out

    def tag(self, s, brk_first=False, brk_last=True):
        """Emit an html tag: breakable at internal spaces; the last piece is
        glued to the following content."""
        pieces = split_tag(s)
        if not pieces:
            return []
        out = []
        for i, p in enumerate(pieces):
            b = (i > 0)
            if i == 0:
                b = brk_first
            if i == len(pieces) - 1:
                b = brk_last
            out.append(Atom(p, b))
        return out

    def fill(self, atoms, width, indent=0):
        if self.wrap == 'none':
            return [''.join(a.s for a in atoms)]
        lines = []
        cur = ''
        pad = ' ' * indent
        for a in atoms:
            if a.brk and cur:
                if len(cur) + 1 + len(a.s) <= width:
                    cur += ' ' + a.s
                else:
                    lines.append(cur)
                    cur = a.s
            else:
                cur += a.s
        if cur or not lines:
            lines.append(cur)
        return [pad + l for l in lines]

    # ---------------- inlines ----------------

    def inline_atoms(self, xs):
        out = []
        for x in xs:
            out.extend(self.inline_atom(x))
        return out

    def inline_atom(self, x):
        t = x.t
        if t == 'Str':
            return self.atoms(x.c[0])
        if t == 'Space':
            return [Atom(' ', True)]
        if t == 'SoftBreak':
            if self.wrap == 'preserve':
                return [Atom('\n')]
            return [Atom(' ', True)]
        if t == 'LineBreak':
            return [Atom('<br />'), Atom('\n')]
        if t == 'Emph':
            return self.wrap_inline('<em>', '</em>', x.c[0])
        if t == 'Strong':
            return self.wrap_inline('<strong>', '</strong>', x.c[0])
        if t == 'Underline':
            return self.wrap_inline('<u>', '</u>', x.c[0])
        if t == 'Strikeout':
            return self.wrap_inline('<del>', '</del>', x.c[0])
        if t == 'Superscript':
            return self.wrap_inline('<sup>', '</sup>', x.c[0])
        if t == 'Subscript':
            return self.wrap_inline('<sub>', '</sub>', x.c[0])
        if t == 'SmallCaps':
            return self.wrap_inline('<span class="smallcaps">', '</span>',
                                    x.c[0])
        if t == 'Quoted':
            if x.c[0].t == 'DoubleQuote':
                return self.wrap_inline('\u201c', '\u201d', x.c[1])
            return self.wrap_inline('\u2018', '\u2019', x.c[1])
        if t == 'Code':
            a = x.c[0]
            open_ = '<code>'
            if a[1]:
                open_ = '<code class="%s">' % esc(' '.join(a[1]))
            return self.tag(open_) + [Atom(esc(x.c[1])), Atom('</code>')]
        if t == 'Math':
            return self.math_atoms(x)
        if t == 'RawInline':
            return [Atom(x.c[1], True)]
        if t == 'Link':
            return self.link_atoms(x)
        if t == 'Image':
            return self.image_atoms(x)
        if t == 'Note':
            return self.note_atoms(x)
        if t == 'Span':
            a = x.c[0]
            s = '<span'
            if a[0]:
                s += ' id="%s"' % esc(a[0])
            if a[1]:
                s += ' class="%s"' % esc(' '.join(a[1]))
            for k, v in a[2]:
                s += ' %s="%s"' % (esc(k), esc(v))
            s += '>'
            out = self.tag(s)
            out.extend(self.inline_atoms(x.c[1]))
            out.append(Atom('</span>'))
            return out
        if t == 'Cite':
            return self.atoms(inline_text([x]), True)
        return [Atom(esc(inline_text([x])), True)]

    def wrap_inline(self, pre, post, xs):
        out = self.tag(pre)
        out.extend(self.inline_atoms(xs))
        out.append(Atom(post))
        return out

    def link_atoms(self, x):
        a = x.c[0]
        s = '<a href="%s"' % esc_url(x.c[2][0])
        if x.c[2][1]:
            s += ' title="%s"' % esc(x.c[2][1])
        if a[0]:
            s += ' id="%s"' % esc(a[0])
        if a[1]:
            s += ' class="%s"' % esc(' '.join(a[1]))
        for k, v in a[2]:
            s += ' %s="%s"' % (esc(k), esc(v))
        s += '>'
        out = self.tag(s, brk_last=True)
        out.extend(self.inline_atoms(x.c[1]))
        out.append(Atom('</a>'))
        return out

    def image_atoms(self, x):
        a = x.c[0]
        alt = inline_text(x.c[1])
        title = x.c[2][1]
        s = '<img src="%s"' % esc_url(x.c[2][0])
        if title:
            s += ' title="%s"' % esc(title)
        if alt:
            s += ' alt="%s"' % esc(alt)
        if a[0]:
            s += ' id="%s"' % esc(a[0])
        if a[1]:
            s += ' class="%s"' % esc(' '.join(a[1]))
        for k, v in a[2]:
            s += ' %s="%s"' % (esc(k), esc(v))
        s += ' />'
        return self.tag(s, brk_last=True)

    def note_atoms(self, x):
        n = len(self.notes) + 1
        self.notes.append((n, x.c[0]))
        s = ('<a href="#fn%d" class="footnote-ref" id="fnref%d" '
             'role="doc-noteref"><sup>%d</sup>' % (n, n, n))
        return self.tag(s) + [Atom('</a>')]

    def math_atoms(self, x):
        from .mathml import math_atoms
        return math_atoms(self, x)

    # ---------------- blocks ----------------

    def block_lines(self, b, indent=0):
        pad = ' ' * indent
        t = b.t
        if t in ('Plain', 'Para'):
            return self.fill(self.inline_atoms(b.c[0]), self.width, indent)
        if t == 'Header':
            return self.header_lines(b, indent)
        if t == 'HorizontalRule':
            return [pad + '<hr />']
        if t == 'CodeBlock':
            return self.code_block_lines(b, indent)
        if t == 'RawBlock':
            return [pad + l for l in b.c[1].split('\n')]
        if t == 'BlockQuote':
            inner = []
            for bl in b.c[1]:
                inner.extend(self.block_lines(bl))
            return [pad + '<blockquote>'] + inner + [pad + '</blockquote>']
        if t == 'BulletList':
            out = [pad + '<ul>']
            for item in b.c[0]:
                out.extend(self.list_item(item, '<li>', '</li>', indent))
            out.append(pad + '</ul>')
            return out
        if t == 'OrderedList':
            out = [pad + self.open_ordered(b)]
            for item in b.c[2]:
                out.extend(self.list_item(item, '<li>', '</li>', indent))
            out.append(pad + '</ol>')
            return out
        if t == 'DefinitionList':
            return self.deflist_lines(b, indent)
        if t == 'Div':
            attrs = self.attr_string(b.c[0])
            open_ = '<div%s>' % attrs
            inner = []
            for bl in b.c[1]:
                inner.extend(self.block_lines(bl, indent))
            return [pad + open_] + inner + [pad + '</div>']
        if t == 'Figure':
            return self.figure_lines(b, indent)
        if t == 'Table':
            return self.table_lines(b, indent)
        if t == 'LineBlock':
            inner = []
            for i, line in enumerate(b.c[0]):
                if i:
                    inner.append(Atom('<br />', False))
                    inner.append(Atom('\n', False))
                inner.extend(self.inline_atoms(line))
            return [pad + '<div class="line-block">' + ''.join(
                a.s for a in inner) + '</div>']
        return [pad + esc(inline_text([b]))]

    def list_item(self, item, pre, post, indent):
        pad = ' ' * indent
        out = []
        body = []
        first = True
        for bl in item:
            if bl.t in ('Para', 'Plain'):
                ls = self.fill(self.inline_atoms(bl.c[0]), self.width, indent)
            else:
                ls = self.block_lines(bl, indent)
            if first:
                out.append(pad + pre + (ls[0][indent:] if ls else ''))
                out.extend(ls[1:])
                first = False
            else:
                out.extend(ls)
        if out:
            out[-1] = out[-1] + post
        else:
            out.append(pad + pre + post)
        return out

    def deflist_lines(self, b, indent):
        pad = ' ' * indent
        out = [pad + '<dl>']
        for item in b.c[0]:
            term = self.fill(self.inline_atoms(item[0]), self.width, indent)
            out.append(pad + '<dt>' + term[0][indent:] + '</dt>')
            if len(term) > 1:
                out.extend(term[1:])
            for d in item[1]:
                if d.t == 'Plain':
                    out.append(pad + '<dd>')
                    out.extend(self.block_lines(d, indent))
                    out.append(pad + '</dd>')
                else:
                    out.append(pad + '<dd>')
                    out.extend(self.block_lines(d, indent))
                    out.append(pad + '</dd>')
        out.append(pad + '</dl>')
        return out

    def open_ordered(self, b):
        style = b.c[0][1].t
        start = b.c[0][0]
        m = {'Decimal': '1', 'LowerAlpha': 'a', 'UpperAlpha': 'A',
             'LowerRoman': 'i', 'UpperRoman': 'I'}[style]
        s = '<ol'
        if start != 1:
            s += ' start="%d"' % start
        s += ' type="%s">' % m
        return s

    def header_lines(self, b, indent):
        level = b.c[0]
        text = self.inline_atoms(b.c[2])
        ident = self.header_id(b)
        if self.o.get('number-sections'):
            num = self.section_number()
            if num:
                text = self.tag('<span class="header-section-number">%s</span>'
                                % num) + [Atom(' ', True)] + text
        open_ = '<h%d id="%s">' % (level, ident)
        out = self.fill(self.tag(open_) + text +
                        self.tag('</h%d>' % level, brk_last=False),
                        self.width, indent)
        return out

    def header_id(self, b):
        if b.c[1][0]:
            return b.c[1][0]
        txt = inline_text(b.c[2])
        base = slugify(txt)
        n = self.header_ids.get(base, 0)
        self.header_ids[base] = n + 1
        return base if n == 0 else '%s-%d' % (base, n)

    def code_block_lines(self, b, indent):
        a = b.c[0]
        txt = b.c[1].rstrip('\n')
        pad = ' ' * indent
        if not a[1]:
            return [pad + '<pre><code>' + esc(txt) + '</code></pre>']
        lang = a[1][0] if a[1] else ''
        ident = a[0] or self.next_code_id()
        cls = ' '.join(a[1])
        inner = self.highlight(txt, lang, ident)
        return [pad + '<div class="sourceCode" id="%s"><pre' % ident,
                pad + 'class="sourceCode %s"><code class="sourceCode %s">%s'
                '</code></pre></div>' % (cls, lang, inner)]

    def next_code_id(self):
        self._cbn += 1
        return 'cb%d' % self._cbn

    def highlight(self, txt, lang, ident):
        from .highlight import highlight_code
        return highlight_code(txt, lang, ident)

    def figure_lines(self, b, indent):
        pad = ' ' * indent
        cap = b.c[1]
        body = []
        for bl in b.c[2]:
            body.extend(self.block_lines(bl, indent))
        caption_text = None
        if cap[0]:
            caption_text = self.inline_atoms(cap[0])
        elif len(cap[1]) == 1 and cap[1][0].t == 'Plain':
            caption_text = self.inline_atoms(cap[1][0].c[0])
        out = [pad + '<figure>']
        out.extend(body)
        if caption_text is not None:
            out.append(pad + '<figcaption aria-hidden="true">' +
                       ''.join(a.s for a in caption_text) +
                       '</figcaption>')
        out.append(pad + '</figure>')
        return out

    def table_lines(self, b, indent):
        pad = ' ' * indent
        out = [pad + '<table>']
        cap = b.c[1]
        if cap[1]:
            caplines = []
            for bl in cap[1]:
                caplines.extend(self.block_lines(bl))
            if len(caplines) == 1:
                out.append(pad + '<caption>' + caplines[0][len(pad):] +
                           '</caption>')
            else:
                out.append(pad + '<caption>')
                out.extend(caplines)
                out.append(pad + '</caption>')
        head = b.c[3]
        if head[1]:
            out.append(pad + '<thead>')
            for r in head[1]:
                out.extend(self.row_lines(r, 'th', indent))
            out.append(pad + '</thead>')
        for bd in b.c[4]:
            out.append(pad + '<tbody>')
            for r in bd[3]:
                out.extend(self.row_lines(r, 'td', indent))
            out.append(pad + '</tbody>')
        foot = b.c[5]
        if foot[1]:
            out.append(pad + '<tfoot>')
            for r in foot[1]:
                out.extend(self.row_lines(r, 'td', indent))
            out.append(pad + '</tfoot>')
        out.append(pad + '</table>')
        return out

    def row_lines(self, r, tag, indent):
        pad = ' ' * indent
        out = [pad + '<tr>']
        for c in r[1]:
            attrs = ''
            style = self.align_style(c[1])
            if style:
                attrs += ' style="%s"' % style
            if c[2] != 1:
                attrs += ' rowspan="%d"' % c[2]
            if c[3] != 1:
                attrs += ' colspan="%d"' % c[3]
            inner = []
            for bl in c[4]:
                inner.extend(self.block_lines(bl))
            if len(inner) == 1:
                out.append(pad + '<%s%s>%s</%s>' % (tag, attrs,
                                                    inner[0][len(pad):],
                                                    tag))
