            lines.append('<section id="footnotes" class="footnotes '
                         'footnotes-end-of-document" role="doc-endnotes">')
            lines.append('<hr />')
            lines.append('<ol>')
            for n, blocks in self.notes:
                inner = []
                for bl in blocks:
