    def includes(self, opts, key):
        out = []
        if opts.has(key):
            for f in (opts.get(key) if isinstance(opts.get(key), list)
                      else [opts.get(key)]):
                try:
                    with open(f, encoding='utf-8') as fh:
                        out.append(fh.read())
                except OSError:
                    pass
        return out

    def render_toc(self, doc):
        out = ['<ul>']
        self._toc(doc.blocks, out, [])
        out.append('</ul>')
        return '\n'.join(out)

    def _toc(self, blocks, out, nums):
        n = 0
        started = False
        for b in blocks:
            if b.t == 'Header':
                level = b.c[0]
                n += 1
                nums2 = nums + [n]
