                out.append(' ')
            elif t == 'SoftBreak':
                out.append(' ')
            elif t == 'LineBreak':
                out.append('\n')
            elif t in ('Code', 'Math'):
                out.append(x.c[1])
            elif t == 'RawInline':
                out.append(x.c[1])
            elif t == 'Link':
                out.append(inline_text(x.c[1]))
            elif t == 'Image':
                out.append(inline_text(x.c[1]))
