                       'Superscript', 'Subscript', 'SmallCaps', 'Span',
                       'Quoted'):
                out.append(inline_text(x.c[1]))
            elif t == 'Note':
                out.append('')
            elif t == 'Cite':
                out.append(inline_text(x.c[1]))
        else:
            out.append(str(x))
    return ''.join(out)
