"""HTML writer."""
import re

from .ast import (El, Doc, Str, Para, Plain, Header, CodeBlock, BlockQuote,
                  BulletList, OrderedList, DefinitionList, HorizontalRule,
                  Div, Figure, LineBlock, RawBlock, Table, Note, Span)


class Atom:
    """A piece of html output; brk says whether a soft break may be
    inserted before it."""
    __slots__ = ('s', 'brk')

    def __init__(self, s, brk=False):
        self.s = s
        self.brk = brk


def esc(s):
    out = []
    for ch in s:
        if ch == '<':
            out.append('&lt;')
        elif ch == '>':
            out.append('&gt;')
        elif ch == '&':
            out.append('&amp;')
        elif ch == '"':
            out.append('&quot;')
        else:
            out.append(ch)
    return ''.join(out)


def esc_url(s):
    out = []
    for ch in s:
        if ch == '"':
            out.append('%22')
        elif ch == '&':
            out.append('&amp;')
        elif ch == '<':
            out.append('&lt;')
        elif ch == '>':
            out.append('&gt;')
        else:
            out.append(ch)
    return ''.join(out)


def slugify(s):
    parts = re.split(r'[ \t\n]+', s.lower())
    keep = []
    for p in parts:
        p2 = ''.join(c for c in p if c.isalnum() or c in '._-')
        if p2:
            keep.append(p2)
    if not keep:
        return 'section'
    return '-'.join(keep)


def split_tag(s):
    """Split an html tag string at spaces not inside quotes; returns a list
    of pieces (the first without a leading space, the rest with)."""
    out = []
    cur = ''
    q = None
    for ch in s:
        if q:
            cur += ch
            if ch == q:
                q = None
            continue
        if ch in '"\'':
            q = ch
            cur += ch
            continue
        if ch == ' ':
            if cur:
                out.append(cur)
                cur = ''
            continue
        cur += ch
    if cur:
        out.append(cur)
    return out


class HtmlWriter:
    def __init__(self, opts):
        self.o = opts
        self.ids = {}
        self.notes = []
        self.header_ids = {}
        self.width = opts.get('columns', 72)
        self.wrap = opts.get('wrap', 'auto')
        self._cbn = 0

    # ---------------- atoms ----------------

    def atoms(self, s, brk=False):
        """Split text into atoms at spaces (nbsp not breakable)."""
        out = []
        if not s:
            return out
        parts = re.split(r'( +)', s)
        first = True
        for p in parts:
            if p == '':
                continue
            if set(p) <= {' ', '\t'}:
                out.append(Atom(p.replace('\t', ' '), True))
                continue
            out.append(Atom(esc(p), brk or not first))
            first = False
        return out

    def tag(self, s, brk_first=False, brk_last=True):
        """Emit an html tag: breakable at internal spaces; the last piece is
        glued to the following content."""
        pieces = split_tag(s)
        if not pieces:
            return []
        out = []
        for i, p in enumerate(pieces):
            b = (i > 0)
            if i == 0:
                b = brk_first
            if i == len(pieces) - 1:
                b = brk_last
            out.append(Atom(p, b))
        return out

    def fill(self, atoms, width, indent=0):
        if self.wrap == 'none':
            return [''.join(a.s for a in atoms)]
        lines = []
        cur = ''
        pad = ' ' * indent
        for a in atoms:
            if a.brk and cur:
                if len(cur) + 1 + len(a.s) <= width:
                    cur += ' ' + a.s
                else:
                    lines.append(cur)
                    cur = a.s
            else:
                cur += a.s
        if cur or not lines:
            lines.append(cur)
        return [pad + l for l in lines]

