        for x in xs:
            out.extend(self.inline_atom(x))
        return out

    def inline_atom(self, x):
        t = x.t
        if t == 'Str':
            return self.atoms(x.c[0])
        if t == 'Space':
            return [Atom(' ', True)]
        if t == 'SoftBreak':
            if self.wrap == 'preserve':
                return [Atom('\n')]
            return [Atom(' ', True)]
        if t == 'LineBreak':
            return [Atom('<br />'), Atom('\n')]
        if t == 'Emph':
            return self.wrap_inline('<em>', '</em>', x.c[0])
        if t == 'Strong':
            return self.wrap_inline('<strong>', '</strong>', x.c[0])
        if t == 'Underline':
            return self.wrap_inline('<u>', '</u>', x.c[0])
        if t == 'Strikeout':
            return self.wrap_inline('<del>', '</del>', x.c[0])
        if t == 'Superscript':
            return self.wrap_inline('<sup>', '</sup>', x.c[0])
        if t == 'Subscript':
            return self.wrap_inline('<sub>', '</sub>', x.c[0])
        if t == 'SmallCaps':
