"""Pandoc AST representation and encoders (JSON / native).

The representation mirrors pandoc's JSON API: an element is a tag plus a
list of components.  For constructors whose only component is a list, the
component list is used directly as `c`.
"""

API_VERSION = [1, 23, 1, 2]


class El:
    __slots__ = ('t', 'c')

    def __init__(self, t, c=None):
        self.t = t
        self.c = c

    def __repr__(self):
        return 'El(%r, %r)' % (self.t, self.c)

    def __eq__(self, other):
        return isinstance(other, El) and other.t == self.t and other.c == self.c

    def __hash__(self):
        return hash((self.t, str(id(self.c))))


def els(t, xs):
    """Element whose single component is a list."""
    return El(t, list(xs))


# ---------------- constructors ----------------

def Str(s):
    return El('Str', s)


def Space():
    return El('Space')


def SoftBreak():
    return El('SoftBreak')


def LineBreak():
    return El('LineBreak')


def Para(inlines):
    return els('Para', inlines)


def Plain(inlines):
    return els('Plain', inlines)


def Header(level, aid, inlines):
    return El('Header', [level, aid, list(inlines)])


def CodeBlock(aid, text):
    return El('CodeBlock', [aid, text])


def Code(aid, text):
    return El('Code', [aid, text])


def Emph(x):
    return els('Emph', x)


def Strong(x):
    return els('Strong', x)


def Underline(x):
    return els('Underline', x)


def Strikeout(x):
    return els('Strikeout', x)


def Superscript(x):
    return els('Superscript', x)


def Subscript(x):
    return els('Subscript', x)


def SmallCaps(x):
    return els('SmallCaps', x)


