{"command": "cat > /workspace/src/pandoc_cli/plain.py <<'PYEOF'
"""Plain text writer."""
import re

from .ast import (El, Str, Para, Plain, Header, CodeBlock, BlockQuote,
                  BulletList, OrderedList, DefinitionList, HorizontalRule,
                  Div, Figure, LineBlock, RawBlock, Table, Note, Span,
                  INLINE_MATH, DISPLAY_MATH)


class PlainWriter:
    def __init__(self, opts):
        self.o = opts
        self.width = opts.get('columns', 72)
        self.wrap = opts.get('wrap', 'auto')
        self.note_counter = 0
        self.notes = []

    def write(self, doc):
        lines = []
        for b in doc.blocks:
            lines.extend(self.block_lines(b))
        if self.notes:
            for n, blocks in self.notes:
                inner = self.blocks_to_text(blocks)
                lines.append('[%d] %s' % (n, inner))
        out = '\n'.join(lines)
        if out and not out.endswith('\n'):
            out += '\n'
        return out

    def blocks_to_text(self, blocks):
        ls = []
        for b in blocks:
            ls.extend(self.block_lines(b))
        return ' '.join(ls).strip()

    # ---------------- wrapping ----------------

    def fill(self, text, indent=0):
        """Wrap text to the width, honouring existing newlines."""
        pad = ' ' * indent
        out = []
        for seg in text.split('\n'):
            if self.wrap == 'none':
                out.append(pad + seg)
                continue
            words = re.split(r'( +)', seg)
            cur = ''
            for w in words:
                if w == '':
                    continue
                if set(w) <= {' '}:
                    if not cur:
                        continue
                    cur += w
                    continue
                if cur and len(cur) + 1 + len(w) > self.width:
                    out.append(cur.rstrip())
                    cur = w
                elif cur:
                    cur += ' ' + w
                else:
                    cur = w
            out.append(cur.rstrip())
        return [pad + l for l in out]

    # ---------------- inlines ----------------

    def inline_text(self, xs):
        out = []
        for x in xs:
            if not isinstance(x, El):
                out.append(str(x))
                continue
            t = x.t
            if t == 'Str':
                out.append(x.c)
            elif t == 'Space':
                out.append(' ')
            elif t == 'SoftBreak':
                out.append(' ')
            elif t == 'LineBreak':
                out.append('\n')
            elif t == 'Code':
                out.append(x.c[1])
            elif t == 'Math':
                out.append(self.math_text(x.c[0], x.c[1]))
            elif t == 'RawInline':
                out.append('')
            elif t in ('Link',):
                out.append(self.inline_text(x.c[1]))
            elif t == 'Image':
                alt = self.inline_text(x.c[1])
                out.append('[%s]' % alt)
            elif t == 'Note':
                self.note_counter += 1
                n = self.note_counter
                self.notes.append((n, x.c))
                out.append('[%d]' % n)
            elif t == 'Strikeout':
                out.append('~~' + self.inline_text(x.c) + '~~')
            elif t == 'Quoted':
                if x.c[0].t == 'DoubleQuote':
                    out.append('\u201c' + self.inline_text(x.c[1]) + '\u201d')
                else:
                    out.append('\u2018' + self.inline_text(x.c[1]) + '\u2019')
            elif t == 'Superscript':
                out.append(self.to_sup(self.inline_text(x.c)))
            elif t == 'Subscript':
                out.append(self.to_sub(self.inline_text(x.c)))
            elif t in ('Emph', 'Strong', 'Underline', 'SmallCaps', 'Span',
                       'Cite'):
                out.append(self.inline_text(x.c[-1]))
            else:
                out.append('')
        return ''.join(out)

    SUP = {'1': '\u00b9', '2': '\u00b2', '3': '\u00b3', '0': '\u2070',
           '4': '\u2074', '5': '\u2075', '6': '\u2076', '7': '\u2077',
           '8': '\u2078', '9': '\u2079', '+': '\u207a', '-': '\u207b',
           '=': '\u207c', '(': '\u207d', ')': '\u207e', 'n': '\u207f'}

    SUB = {'0': '\u2080', '1': '\u2081', '2': '\u2082', '3': '\u2083',
           '4': '\u2084', '5': '\u2085', '6': '\u2086', '7': '\u2087',
           '8': '\u2088', '9': '\u2089', '+': '\u208a', '-': '\u208b',
           '=': '\u208c', '(': '\u208d', ')': '\u208e', 'n': '\u2099'}

    def to_sup(self, s):
        return ''.join(self.SUP.get(c, c) for c in s)

    def to_sub(self, s):
        return ''.join(self.SUB.get(c, c) for c in s)

    def math_text(self, mtype, tex):
        from .texmath import tex_to_plain
        return tex_to_plain(tex)

    # ---------------- blocks ----------------

    def block_lines(self, b, indent=0):
        t = b.t
        if t in ('Plain', 'Para'):
            return self.fill(self.inline_text(b.c), indent)
        if t == 'Header':
            return self.fill(self.inline_text(b.c[2]), indent)
        if t == 'HorizontalRule':
            return ['-' * 72]
        if t == 'CodeBlock':
            return self.fill(b.c[1].rstrip('\n'), indent + 4)
        if t == 'RawBlock':
            return []
        if t == 'BlockQuote':
            inner = []
            for bl in b.c:
                inner.extend(self.block_lines(bl, indent + 2))
            return self.insert_blanks(inner)
        if t == 'BulletList':
            out = []
            for item in b.c:
                out.extend(self.list_item(item, '- ', 2, indent))
            return out
        if t == 'OrderedList':
            out = []
            start, style, delim = b.c[0]
            for i, item in enumerate(b.c[1]):
                marker = self.marker(start + i, style, delim)
                out.extend(self.list_item(item, marker + ' ', len(marker) + 3,
                                          indent))
            return out
        if t == 'DefinitionList':
            out = []
            for item in b.c:
                out.extend(self.fill(self.inline_text(item[0]), indent))
                for d in item[1]:
                    out.extend(self.block_lines(d, indent + 2))
            return out
        if t == 'Div':
            out = []
            for bl in b.c[1]:
                out.extend(self.block_lines(bl, indent))
            return out
        if t == 'Figure':
            out = []
            for bl in b.c[2]:
                out.extend(self.block_lines(bl, indent))
            return out
        if t == 'Table':
            return self.table_lines(b, indent)
        if t == 'LineBlock':
            return self.fill(' | '.join(self.inline_text(l) for l in b.c),
                             indent)
        return [indent * ' ' + self.inline_text(getattr(b, 'c', []))]

    def insert_blanks(self, lines):
        """Insert a blank line between paragraphs in a blockquote."""
        out = []
        prev = None
        for l in lines:
            if prev is not None and l and not l.startswith('  ') and prev:
                pass
            out.append(l)
            prev = l
        return out

    def list_item(self, item, marker, cont_indent, indent):
        pad = ' ' * indent
        out = []
        first = True
        for bl in item:
            if bl.t in ('Para', 'Plain'):
                ls = self.fill(self.inline_text(bl.c), indent)
            else:
                ls = self.block_lines(bl, indent)
            if first:
                out.append(pad + marker + (ls[0][indent:] if ls else ''))
                out.extend(ls[1:])
                first = False
            else:
                out.extend(ls)
        return out

    def marker(self, n, style, delim):
        s = style.t
        if s == 'Decimal':
            v = str(n)
        elif s == 'LowerAlpha':
            v = self.alpha(n, False)
        elif s == 'UpperAlpha':
            v = self.alpha(n, True)
        elif s == 'LowerRoman':
            v = self.roman(n).lower()
        else:
            v = self.roman(n)
        return v + ('.' if delim.t == 'Period' else ')')

    def alpha(self, n, upper):
        s = ''
        while n > 0:
            n -= 1
            s = chr(ord('a' if not upper else 'A') + n % 26) + s
            n //= 26
        return s or 'a'

    def roman(self, n):
        vals = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
                (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'),
                (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')]
        out = ''
        for v, sym in vals:
            while n >= v:
                out += sym
                n -= v
        return out

    # ---------------- tables ----------------

    def table_lines(self, b, indent):
        pad = ' ' * indent
        head = b.c[3]
        bodies = b.c[4]
        rows = []
        for r in head[1]:
            rows.append([self.cell_text(c) for c in r[1]])
        for bd in bodies:
            for r in bd[3]:
