"""Haskell-style float formatting (for JSON output of ColWidth etc.)."""


def show_double(v):
    """Format a float the way GHC's `show` does."""
    if v != v:
        return 'NaN'
    if v == float('inf'):
        return 'Infinity'
    if v == float('-inf'):
        return '-Infinity'
    if v == 0:
        return '0.0' if str(v)[0] != '-' else '-0.0'
    if v < 0:
        return '-' + show_double(-v)
    r = repr(v)
    if 'e' in r or 'E' in r:
        return _from_exp(r)
    # find the shortest representation, preferring exponent if shorter
    best = r
    bestlen = _sigdigits(r)
    for d in range(1, 18):
        cand = _fmt_exp(v, d)
        if cand is None:
            continue
        try:
            if float(cand) == v:
                n = _sigdigits(cand)
                if n < bestlen:
                    best = cand
                    bestlen = n
                    break
        except Exception:
            pass
    return best


def _sigdigits(s):
    s = s.lower()
    if 'e' in s:
        mant = s.split('e')[0]
    else:
        mant = s
    mant = mant.lstrip('-')
    if '.' in mant:
        a, b = mant.split('.')
    else:
        a, b = mant, ''
    digits = (a + b).lstrip('0')
    return len(digits.rstrip('0')) if digits.rstrip('0') else 1


def _fmt_exp(v, digits):
    """Format v in exponent notation with `digits` significant digits."""
    if digits < 1:
        return None
    import math
    if v == 0:
        return '0.0e0'
    e = int(math.floor(math.log10(v)))
    # adjust
    for _ in range(-2, 3):
        s = '%.*e' % (digits - 1, v)
        mant, exp = s.split('e')
        if float(mant) >= 10:
            e += 1
        elif float(mant) < 1:
            e -= 1
        else:
            break
        s = '%.*e' % (digits - 1, v * (10 ** -e))
        mant, exp = s.split('e')
    mant = mant.replace('.', '')
    while len(mant) > digits:
        mant = mant[:-1]
    while len(mant) < digits:
        mant += '0'
    out = mant[0]
    if len(mant) > 1:
        out += '.' + mant[1:]
    else:
        out += '.0'
    out += 'e%d' % e
    return out


def _from_exp(r):
    """Convert Python's exponent notation to Haskell's."""
    r = r.lower()
    mant, exp = r.split('e')
    e = int(exp)
    if '.' not in mant:
        mant += '.0'
    if len(mant.split('.')[1]) == 0:
        mant += '0'
    return '%se%d' % (mant, e)
